cat > /tmp/build_lms.py << 'PYEOF' html =r"""<!DOCTYPE html> <html lang="en"data-theme="dark"> <head> <metacharset="UTF-8"/><meta name="viewport"content="width=device-width,initial-scale=1.0"/> <title>TSTech Park — LMS</title> <link rel="preconnect"href="https://fonts.googleapis.com"/> <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700;800&display=swap"rel="stylesheet"/> <link rel="stylesheet"href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"/><style> :root{ --bg:#06080f;--bg2:#0d1117;--bg3:#131b2e;--primary:#0d1117;--accent:#00e5ff;--accent2:#7c4dff;--accentr:#ff3d71;--gold:#ffd600;--green:#00e676;--teal:#00e5ff;--text:#e8f4ff;--text2:#7a8db0;--border:#1e2d45; --shadow:0 4px 20pxrgba(0,230,255,.05); --shadow-lg:0 12px 48px rgba(0,0,0,.7);--r:14px;--r-sm:8px;--nav-h:60px;--tr:all .18s ease; }[data-theme="light"]{ --bg:#f0f5ff;--bg2:#fff;--bg3:#e8f0ff;--primary:#0a0f2e;--text:#0d1b3e;--text2:#5a6a8a;--border:#d0ddf0; --shadow:04px 20px rgba(0,0,0,.08);--shadow-lg:0 12px 48px rgba(0,0,0,.18); }*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}html{scroll-behavior:smooth}body{font-family:'Inter',sans-serif;background:var(--bg);color:var(--text);overflow-x:hidden;padding-bottom:62px}h1,h2,h3,h4{font-family:'Space Grotesk',sans-serif} button,textarea,input,select{font-family:'Inter',sans-serif}/* NAV */.navbar{position:fixed;top:0;left:0;right:0;z-index:900;height:var(--nav-h);background:rgba(13,17,23,.96);backdrop-filter:blur(18px); border-bottom:1pxsolid var(--border); display:flex;align-items:center;justify-content:space-between;padding:01.3rem;gap:8px}.logo{display:flex;align-items:center;gap:9px;text-decoration:none;flex-shrink:0}.logo-mark{width:34px;height:34px;background:linear-gradient(135deg,var(--accent),var(--accent2));border-radius:9px;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:12px;color:#000;font-family:'SpaceGrotesk',sans-serif}.logo-text{color:var(--text);font-size:15px;font-weight:700;line-height:1.2}.logo-sub{color:var(--text2);font-size:9px;font-weight:400;display:block}.nav-links{display:flex;align-items:center;gap:1px;flex:1;justify-content:center}.nav-link{color:var(--text2);background:none;border:none;padding:6px10px;border-radius:7px; font-size:12px;font-weight:500;cursor:pointer;transition:var(--tr);display:flex;align-items:center;gap:4px;white-space:nowrap}.nav-link:hover,.nav-link.active{color:var(--accent);background:rgba(0,229,255,.08)}.nav-actions{display:flex;align-items:center;gap:6px;flex-shrink:0}.icon-btn{width:32px;height:32px;border-radius:7px;background:var(--bg3);border:1pxsolid var(--border);color:var(--text2);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:13px;transition:var(--tr);position:relative}.icon-btn:hover{color:var(--accent);border-color:var(--accent)}.notif-badge{position:absolute;top:4px;right:4px;width:14px;height:14px;background:var(--accentr);border-radius:50%;font-size:8px;font-weight:800;color:#fff;display:flex;align-items:center;justify-content:center}.btn-sm{padding:6px13px;border-radius:7px;font-size:12px;font-weight:600;cursor:pointer;border:none;transition:var(--tr)}.btn-outline{background:transparent;border:1px solidvar(--accent);color:var(--accent)}.btn-outline:hover{background:rgba(0,229,255,.1)} .btn-primary{background:var(--accent);color:#000}.btn-primary:hover{opacity:.85}.user-av-btn{width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--accent2));border:none;color:#000;font-size:12px;font-weight:800;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:var(--tr)}.user-av-btn:hover{transform:scale(1.1)}.hamburger{display:none;background:none;border:none;color:var(--text);font-size:19px;cursor:pointer}/* notif panel */ .notif-panel{position:absolute;top:42px;right:0;width:300px;background:var(--bg2);border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow-lg);display:none;z-index:2000;overflow:hidden;max-height:80vh;overflow-y:auto}.notif-panel.open{display:block} .ni-hdr{padding:12px 14px8px;border-bottom:1px solidvar(--border);display:flex;justify-content:space-between;align-items:center}.notif-item{padding:10px 14px;border-bottom:1px solidvar(--border);display:flex;gap:9px;cursor:pointer;transition:background .15s}.notif-item:hover{background:var(--bg3)}.notif-item.unread{background:rgba(0,229,255,.03)}.ni-ico{width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:12px;flex-shrink:0}.ni-p{background:rgba(124,77,255,.12);color:var(--accent2)}.ni-g{background:rgba(0,230,118,.12);color:var(--green)}.ni-b{background:rgba(0,132,255,.12);color:#0084ff}.ni-y{background:rgba(255,214,0,.12);color:var(--gold)} /* mob menu */.mob-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.65);z-index:1100}.mob-overlay.open{display:block}.mob-menu{position:fixed;top:0;right:-260px;width:245px;height:100vh;background:var(--bg2);border-left:1px solid var(--border);z-index:1200;transition:right .28s;overflow-y:auto;padding-bottom:2rem}.mob-menu.open{right:0}.mob-hdr{display:flex;justify-content:space-between;align-items:center;padding:14px;border-bottom:1pxsolid var(--border)}.mob-link{display:flex;align-items:center;gap:10px;width:100%;padding:12px 14px;background:none;border:none;color:var(--text2);font-size:13px;font-weight:500;cursor:pointer;text-align:left;transition:var(--tr)}.mob-link:hover{color:var(--accent);background:rgba(0,229,255,.06)} /* PAGES */.page{display:none;padding-top:var(--nav-h);min-height:100vh}.page.active{display:block} .pg-hdr{background:var(--bg2);border-bottom:1pxsolid var(--border);padding:1.8rem 1.5rem 1.6rem}.pg-hdr-inner{max-width:1200px;margin:0 auto} .pg-hdrh2{color:var(--text);font-size:1.7rem;font-weight:800} .pg-hdrp{color:var(--text2);font-size:.9rem;margin-top:4px} /* HERO */.hero{background:var(--bg);min-height:calc(100vh - var(--nav-h));display:flex;align-items:center;padding:3rem1.5rem;position:relative;overflow:hidden} .hero::before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse 70% 50% at 65%40%,rgba(124,77,255,.12),transparent), radial-gradient(ellipse 50% 60% at 20%70%,rgba(0,229,255,.07),transparent); pointer-events:none}.hero-inner{max-width:1200px;margin:0 auto;display:grid;grid-template-columns:1fr1fr; gap:3.5rem;align-items:center;width:100%;position:relative;z-index:1}.hero-badge{display:inline-flex;align-items:center;gap:6px;background:rgba(0,229,255,.1);border:1px solidrgba(0,229,255,.25);color:var(--accent); padding:4px12px;border-radius:18px;font-size:11px;font-weight:700;margin-bottom:1.1rem}.bp{width:6px;height:6px;background:var(--accent);border-radius:50%;animation:pulse1.5s infinite} @keyframespulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.4;transform:scale(.6)}}.heroh1{font-size:2.9rem;font-weight:800;color:var(--text);line-height:1.12;margin-bottom:1rem}.hl{background:linear-gradient(90deg,var(--accent),var(--accent2));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}.herop{color:var(--text2);font-size:.97rem;line-height:1.72;margin-bottom:1.7rem}.hero-btns{display:flex;gap:11px;flex-wrap:wrap;margin-bottom:2.2rem}.btn-hero{padding:12px24px;border-radius:11px;font-size:13px;font-weight:700;cursor:pointer;border:none;transition:var(--tr);display:inline-flex;align-items:center;gap:7px}.bh-main{background:var(--accent);color:#000;box-shadow:0 8px 22pxrgba(0,229,255,.3)} .bh-main:hover{transform:translateY(-2px);box-shadow:0 12px30px rgba(0,229,255,.45)}.bh-ghost{background:rgba(255,255,255,.06);color:var(--text);border:1px solidvar(--border)} .bh-ghost:hover{border-color:var(--accent);color:var(--accent)}.hero-stats{display:flex;align-items:center} .hs-i{text-align:center;padding:016px} .hs-i:first-child{padding-left:0}.hs-n{font-size:1.5rem;font-weight:800;color:var(--accent);display:block;font-family:'SpaceGrotesk',sans-serif} .hs-l{font-size:10px;color:var(--text2)}.hs-div{width:1px;height:28px;background:var(--border)} .hero-right{display:flex;flex-direction:column;gap:11px}.fc{background:rgba(255,255,255,.04);border:1px solidvar(--border);border-radius:14px;padding:14px 16px;animation:ff 4s ease-in-outinfinite} .fc.f1{animation-delay:0s;display:flex;align-items:center;gap:11px}.fc.f2{animation-delay:.6s;display:flex;align-items:center;gap:11px}.fc.f3{animation-delay:1.2s} @keyframesff{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}.fci{width:40px;height:40px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:17px;color:#000;flex-shrink:0}.fcn{color:var(--text);font-weight:700;font-size:12px;margin-bottom:3px}.fcs{color:var(--text2);font-size:10px;margin-bottom:4px}.fcb{height:4px;background:var(--border);border-radius:2px} .fcf{height:100%;border-radius:2px;background:linear-gradient(90deg,var(--accent),var(--accent2))}.cpb{padding:7px10px;border-radius:9px;font-size:11px;margin-bottom:5px;max-width:92%}.cpbot{background:rgba(124,77,255,.15);color:#c4b5fd;border-radius:9px 9px 9px2px}.cpuser{background:rgba(0,229,255,.12);color:var(--accent);margin-left:auto;border-radius:9px9px 2px 9px} /* FEATURES */ .section{padding:4rem 1.5rem}.section-alt{background:var(--bg2)} .section-inner{max-width:1200px;margin:0auto} .s-lbl{font-size:10px;font-weight:800;color:var(--accent);text-transform:uppercase;letter-spacing:2.5px;margin-bottom:7px}.s-title{font-size:1.9rem;font-weight:800;margin-bottom:7px}.s-sub{color:var(--text2);font-size:.9rem;line-height:1.7;max-width:500px}.feat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:2.2rem}.feat-card{background:var(--bg3);border:1px solidvar(--border);border-radius:var(--r);padding:22px 18px;transition:var(--tr)}.feat-card:hover{transform:translateY(-3px);box-shadow:0 8px 28pxrgba(0,229,255,.08);border-color:rgba(0,229,255,.2)}.feat-ico{width:46px;height:46px;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:19px;margin-bottom:12px}.feat-card h3{font-size:14px;font-weight:700;margin-bottom:7px} .feat-cardp{color:var(--text2);font-size:12px;line-height:1.7}.cta-sect{background:linear-gradient(135deg,var(--bg),#0a0a20,rgba(124,77,255,.15));padding:4rem1.5rem;text-align:center;border-top:1px solid var(--border)} .cta-inner{max-width:520px;margin:0auto} .cta-sect h2{font-size:1.8rem;font-weight:800;margin-bottom:9px}.cta-sect p{color:var(--text2);margin-bottom:1.6rem} /* COURSES */.filter-bar{background:var(--bg2);border-bottom:1px solidvar(--border);padding:.8rem 1.5rem;position:sticky;top:var(--nav-h);z-index:100}.filter-inner{max-width:1200px;margin:0auto;display:flex;gap:8px;flex-wrap:wrap;align-items:center}.sb{position:relative} .sb input{width:210px;padding:7px 12px 7px32px;border:1px solid var(--border);border-radius:8px;font-size:12px;background:var(--bg3);color:var(--text);outline:none;transition:border-color.18s} .sb input:focus{border-color:var(--accent)} .sbi{position:absolute;left:9px;top:50%;transform:translateY(-50%);color:var(--text2);font-size:11px;pointer-events:none}.fsel{padding:7px 10px;border:1px solidvar(--border);border-radius:8px;font-size:12px;background:var(--bg3);color:var(--text);outline:none;cursor:pointer}.fsel:focus{border-color:var(--accent)} .fbtn{padding:7px13px;border-radius:8px;font-size:12px;font-weight:600;cursor:pointer;border:1pxsolidvar(--border);background:var(--bg3);color:var(--text2);transition:var(--tr)}.fbtn:hover,.fbtn.active{border-color:var(--accent);color:var(--accent);background:rgba(0,229,255,.06)}.courses-wrap{max-width:1200px;margin:0 auto;padding:0 1.5rem}.courses-res{padding:12px 0 0;font-size:13px;color:var(--text2)}.courses-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px;padding:12px0 2rem} .cc{background:var(--bg2);border:1px solidvar(--border);border-radius:var(--r);overflow:hidden;cursor:pointer;transition:var(--tr)}.cc:hover{transform:translateY(-3px);box-shadow:0 8px 32pxrgba(0,229,255,.08);border-color:rgba(0,229,255,.2)}.cc-thumb{height:140px;display:flex;align-items:center;justify-content:center;font-size:2.8rem;position:relative}.cc-badge{position:absolute;top:9px;right:9px;padding:2px8px;border-radius:5px;font-size:9px;font-weight:800}.badge-hot{background:var(--accentr);color:#fff} .badge-new{background:var(--green);color:#002e15}.cc-wish{position:absolute;top:8px;left:8px;width:28px;height:28px;border-radius:6px;border:1px solidrgba(255,255,255,.2);background:rgba(0,0,0,.4);color:#fff;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:11px;transition:var(--tr)}.cc-wish:hover,.cc-wish.active{background:var(--accentr);border-color:var(--accentr)}.cc-body{padding:13px 14px}.cc-cat{font-size:9px;font-weight:800;color:var(--accent);text-transform:uppercase;letter-spacing:1px;margin-bottom:4px}.cc-title{font-size:13px;font-weight:700;margin-bottom:4px;line-height:1.4}.cc-desc{font-size:11px;color:var(--text2);line-height:1.6;margin-bottom:8px}.cc-meta{display:flex;flex-wrap:wrap;gap:8px;font-size:10px;color:var(--text2);margin-bottom:8px}.cc-meta i{color:var(--accent);margin-right:2px}.cc-rating{display:flex;align-items:center;gap:4px;font-size:10px;margin-bottom:8px}.stars{color:var(--gold)}.cc-footer{display:flex;align-items:center;justify-content:space-between;padding-top:9px;border-top:1pxsolid var(--border)}.cc-price{font-size:15px;font-weight:800;color:var(--accent)}.cc-old{font-size:10px;color:var(--text2);text-decoration:line-through;margin-left:3px}.btn-enroll{padding:6px 13px;background:var(--accent);color:#000;border:none;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;transition:var(--tr)}.btn-enroll:hover{opacity:.85} /* DASHBOARD */.dash-layout{display:grid;grid-template-columns:215px 1fr;min-height:calc(100vh- var(--nav-h))} .sidebar{background:var(--bg2);border-right:1px solidvar(--border);padding:.9rem.6rem;position:sticky;top:var(--nav-h);height:calc(100vh -var(--nav-h));overflow-y:auto}.sb-user{display:flex;align-items:center;gap:8px;padding:8px 8px14px;border-bottom:1px solid var(--border);margin-bottom:10px}.sb-av{width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--accent2));display:flex;align-items:center;justify-content:center;font-weight:800;font-size:13px;color:#000;flex-shrink:0}.sb-name{font-weight:700;font-size:12px}.sb-role{font-size:10px;color:var(--text2)} .sb-section{margin-bottom:14px}.sb-label{font-size:9px;font-weight:800;color:var(--text2);text-transform:uppercase;letter-spacing:1.5px;padding:08px;margin-bottom:3px} .sb-link{display:flex;align-items:center;gap:8px;width:100%;padding:7px8px;border-radius:8px;font-size:12px;font-weight:500;color:var(--text2);cursor:pointer;border:none;background:none;text-align:left;transition:var(--tr)}.sb-link i{width:16px;font-size:13px}.sb-link:hover{background:var(--bg3);color:var(--text)}.sb-link.active{background:rgba(0,229,255,.1);color:var(--accent);font-weight:600}.sb-badge{margin-left:auto;background:var(--accentr);color:#fff;padding:1px5px;border-radius:8px;font-size:9px;font-weight:800}.dash-main{padding:1.5rem;overflow-y:auto}.dash-card{background:var(--bg2);border:1px solidvar(--border);border-radius:var(--r);padding:16px}.dc-title{font-size:13px;font-weight:700;margin-bottom:12px;display:flex;align-items:center;justify-content:space-between}.dc-titlea{font-size:11px;color:var(--accent);text-decoration:none;font-weight:500}.dash-hdr{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:18px;flex-wrap:wrap;gap:9px}.dash-hdr h2{font-size:1.3rem;font-weight:800} .dash-hdrp{color:var(--text2);font-size:12px;margin-top:2px}.stats-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:16px}.stat-card{background:var(--bg2);border:1px solid 