ccent),var(--accent2));display:flex;align-items:center;justify-content:center;font-size:14px;color:#000;flex-shrink:0}.chat-ai-name{color:var(--text);font-weight:700;font-size:12px}.chat-ai-status{color:var(--text2);font-size:10px;display:flex;align-items:center;gap:4px}.online-dot{width:5px;height:5px;background:var(--green);border-radius:50%}.chat-ctrl{width:24px;height:24px;border-radius:6px;background:var(--bg3);border:none;color:var(--text2);cursor:pointer;font-size:11px;display:flex;align-items:center;justify-content:center;transition:var(--tr)}.chat-ctrl:hover{color:var(--accent)} .chat-lang-sel{padding:3px7px;border-radius:6px;background:var(--bg3);border:1px solidvar(--border);color:var(--text);font-size:10px;cursor:pointer;outline:none;margin-left:auto}.chat-msgs{flex:1;padding:11px;overflow-y:auto;display:flex;flex-direction:column;gap:8px}.cmr{display:flex;gap:6px;max-width:92%}.cmr.user{flex-direction:row-reverse;margin-left:auto}.msg-av-sm{width:22px;height:22px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;flex-shrink:0}.bot-av-sm{background:linear-gradient(135deg,var(--accent),var(--accent2));color:#000}.user-av-sm{background:linear-gradient(135deg,var(--accent2),#4f3eff);color:#fff}.msg-bubble{padding:7px11px;border-radius:11px;font-size:11px;line-height:1.55}.bot-bub{background:var(--bg3);border:1px solidvar(--border);color:var(--text);border-radius:11px 11px 11px 2px}.user-bub{background:linear-gradient(135deg,var(--accent),#00aabb);color:#000;border-radius:11px11px 2px 11px} .chat-sugg{padding:0 9px7px;display:flex;flex-wrap:wrap;gap:4px} .sugg-chip{padding:3px 9px;border:1pxsolidvar(--border);border-radius:9px;font-size:10px;cursor:pointer;background:var(--bg3);color:var(--text2);transition:var(--tr)}.sugg-chip:hover{border-color:var(--accent);color:var(--accent)}.chat-input-area{padding:9px;border-top:1px solidvar(--border);display:flex;gap:6px;align-items:flex-end}.chat-input{flex:1;padding:7px 10px;border:1px solidvar(--border);border-radius:9px;font-size:11px;background:var(--bg3);color:var(--text);outline:none;resize:none;max-height:80px;overflow-y:auto;line-height:1.5;transition:border-color.18s} .chat-input:focus{border-color:var(--accent)} .chat-send{width:32px;height:32px;background:var(--accent);border:none;border-radius:8px;color:#000;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:12px;flex-shrink:0}.chatbot-toggle{width:50px;height:50px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--accent2));border:none;cursor:pointer;box-shadow:06px 20pxrgba(0,229,255,.35);display:flex;align-items:center;justify-content:center;font-size:19px;color:#000;transition:var(--tr);position:relative}.chatbot-toggle:hover{transform:scale(1.08)}.chat-ubadge{position:absolute;top:2px;right:2px;width:15px;height:15px;background:var(--gold);color:#4a2e00;border-radius:50%;font-size:8px;font-weight:800;display:flex;align-items:center;justify-content:center}.typing-indicator{display:flex;gap:3px;align-items:center;padding:5px 0}.typing-dot{width:4px;height:4px;background:var(--text2);border-radius:50%;animation:bounce1.2s infinite} .typing-dot:nth-child(2){animation-delay:.2s}.typing-dot:nth-child(3){animation-delay:.4s} @keyframesbounce{0%,80%,100%{transform:translateY(0)}40%{transform:translateY(-5px)}}.warn-msg{background:rgba(255,214,0,.1);border:1px solidrgba(255,214,0,.35);border-radius:9px;padding:7px10px;font-size:11px;color:var(--gold);font-weight:600;display:flex;align-items:center;gap:5px}/* TOASTS */.toast-container{position:fixed;bottom:20px;left:20px;z-index:3000;display:flex;flex-direction:column;gap:6px;pointer-events:none}.toast{background:var(--bg2);border:1px solid var(--border);border-radius:10px;padding:10px13px;box-shadow:var(--shadow-lg);display:flex;align-items:center;gap:8px;font-size:12px;font-weight:500;min-width:220px;max-width:300px;transform:translateY(16px);opacity:0;transition:all.27s;pointer-events:auto} .toast.show{transform:translateY(0);opacity:1}.toast.success i{color:var(--green);font-size:14px} .toast.errori{color:var(--accentr);font-size:14px} .toast.infoi{color:var(--accent);font-size:14px} .toast.warningi{color:var(--gold);font-size:14px} /* MOB NAV */ .mob-bot-nav{display:none;position:fixed;bottom:0;left:0;right:0;z-index:900;background:var(--bg2);border-top:1pxsolid var(--border)} .mbnav-btn{flex:1;padding:8px 3px6px;display:flex;flex-direction:column;align-items:center;gap:2px;border:none;background:none;font-size:9px;color:var(--text2);cursor:pointer;transition:color.18s} .mbnav-btn i{font-size:17px} .mbnav-btn.active{color:var(--accent)}.empty-state{text-align:center;padding:3rem 1.5rem;color:var(--text2)}.empty-state i{font-size:2.3rem;margin-bottom:11px;display:block;opacity:.25}.empty-state p{margin-bottom:11px}@media(max-width:1024px){.admin-grid{grid-template-columns:1fr}.dash-g2{grid-template-columns:1fr}.feat-grid{grid-template-columns:repeat(2,1fr)}.stats-grid{grid-template-columns:repeat(2,1fr)}.admin-stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:860px){.hero-inner{grid-template-columns:1fr}.hero-right{display:none}.heroh1{font-size:2rem}.dash-layout{grid-template-columns:1fr}.sidebar{display:none}.nav-links{display:none}.hamburger{display:block}#guestButtons.btn-outline{display:none}.mob-bot-nav{display:flex}body{padding-bottom:60px}.profile-grid{grid-template-columns:1fr}.chatbot-widget{bottom:72px;right:12px}}@media(max-width:600px){.feat-grid{grid-template-columns:1fr}.stats-grid{grid-template-columns:1fr1fr}.dash-geq{grid-template-columns:1fr}.form-row{grid-template-columns:1fr}.courses-grid{grid-template-columns:1fr}.modal{border-radius:16px16px 0 0;align-self:flex-end;max-height:95vh}.chat-panel{width:295px}} @mediaprint{.navbar,.chatbot-widget,.toast-container,.mob-bot-nav,.sidebar,.filter-bar{display:none!important}.page{padding-top:0}}</style> </head> <body> <nav class="navbar"><a href="#" class="logo"onclick="showPage('home');return false"> <div class="logo-mark">TS</div><div class="logo-text">TS Tech Park<spanclass="logo-sub">A Group of TSInstitutions</span></div> </a> <divclass="nav-links" id="navLinks"> <buttonclass="nav-link active" onclick="showPage('home')"><iclass="fas fa-home"></i>Home</button> <buttonclass="nav-link" onclick="showPage('courses')"><iclass="fas fa-book"></i>Courses</button> <buttonclass="nav-link" onclick="showPage('dashboard')"><iclass="fas fa-th-large"></i>Dashboard</button><button class="nav-link" onclick="showPage('forum')"><iclass="fas fa-comments"></i>Community</button><button class="nav-link"onclick="showPage('live')"><i class="fasfa-video"></i>Live</button> <button class="nav-link"onclick="showPage('admin')"><i class="fasfa-shield-alt"></i>Admin</button> </div> <divclass="nav-actions"> <button class="icon-btn"onclick="toggleTheme()" title="Theme"><iclass="fas fa-moon"id="themeIcon"></i></button> <divstyle="position:relative"> <button class="icon-btn"id="notifBtn" onclick="toggleNotif()"><iclass="fas fa-bell"></i><spanclass="notif-badge"id="notifBadge">4</span></button> <divclass="notif-panel" id="notifPanel"></div></div> <div id="guestButtons" style="display:flex;gap:6px"><button class="btn-sm btn-outline"onclick="openAuth('login')">Login</button> <buttonclass="btn-sm btn-primary"onclick="openAuth('signup')">Sign Up</button> </div><button class="user-av-btn" id="userAvBtn"onclick="showPage('profile')"style="display:none"><spanid="userAvInit">?</span></button> <buttonclass="hamburger" onclick="toggleMob()"><iclass="fas fa-bars"></i></button> </div></nav> <div class="mob-overlay" id="mobOverlay"onclick="closeMob()"></div> <divclass="mob-menu" id="mobMenu"> <divclass="mob-hdr"><spanstyle="font-weight:700;color:var(--text)">Menu</span><buttononclick="closeMob()"style="background:none;border:none;color:var(--text2);font-size:17px;cursor:pointer"><iclass="fas fa-times"></i></button></div><button class="mob-link"onclick="showPage('home');closeMob()"><i class="fasfa-home"></i>Home</button> <buttonclass="mob-link"onclick="showPage('courses');closeMob()"><i class="fasfa-book"></i>Courses</button> <buttonclass="mob-link"onclick="showPage('dashboard');closeMob()"><i class="fasfa-th-large"></i>Dashboard</button> <buttonclass="mob-link"onclick="showPage('forum');closeMob()"><i class="fasfa-comments"></i>Community</button> <buttonclass="mob-link"onclick="showPage('live');closeMob()"><i class="fasfa-video"></i>Live Classes</button> <buttonclass="mob-link" onclick="showPage('admin');closeMob()"><iclass="fas fa-shield-alt"></i>Admin</button> <divstyle="padding:12px"><button class="btn-fullbtn-accent"onclick="openAuth('login');closeMob()">Login</button></div></div> <!-- HOME --> <div id="page-home"class="page active"> <section class="hero"><div class="hero-inner"> <div> <divclass="hero-badge"><span class="bp"></span>India's#1 Embedded & AI Learning Platform</div> <h1>Master <spanclass="hl">Future-Ready</span><br>TechSkills</h1> <p>Join 50,000+ students learning Embedded Systems, AI,IoT, Edge Computing and more — guided by industry experts at TS TechPark.</p> <div class="hero-btns"> <buttonclass="btn-hero bh-main"onclick="showPage('courses')"><i class="fasfa-rocket"></i>Explore Courses</button> <buttonclass="btn-hero bh-ghost"onclick="showPage('live')"><i class="fasfa-play-circle"></i>Watch Demo</button> </div><div class="hero-stats"> <divclass="hs-i"><spanclass="hs-n">50+</span><spanclass="hs-l">Courses</span></div> <divclass="hs-div"></div> <divclass="hs-i"><span class="hs-n">50K+</span><spanclass="hs-l">Students</span></div> <divclass="hs-div"></div> <divclass="hs-i"><spanclass="hs-n">98%</span><span class="hs-l">Placement</span></div><div class="hs-div"></div> <divclass="hs-i"><spanclass="hs-n">15+</span><spanclass="hs-l">Awards</span></div> </div></div> <div class="hero-right"> <div class="fcf1"><div class="fci"style="background:linear-gradient(135deg,#00e5ff,#0088aa)"><iclass="fas fa-microchip"></i></div><div><divclass="fcn">Automotive Embedded</div><div class="fcs">72%complete</div><div class="fcb"><divclass="fcf"style="width:72%"></div></div></div></div><div class="fc f2"><div class="fci" style="background:linear-gradient(135deg,#7c4dff,#4f3eff)"><iclass="fas fa-brain"></i></div><div><divclass="fcn">Edge AI & Deep Learning</div><divclass="fcs">45% complete</div><divclass="fcb"><div class="fcf"style="width:45%"></div></div></div></div><div class="fc f3"> <divstyle="font-size:11px;font-weight:700;color:var(--text2);margin-bottom:8px"><iclass="fas fa-robot"style="color:var(--accent);margin-right:4px"></i>TechBot AITutor</div> <div class="cpb cpbot"> Ask me in Tamil, Hindi, Telugu or English!</div> <div class="cpbcpuser">RTOS என்றால்என்ன?</div><div class="cpb cpbot">RTOS என்பதுReal-Time Operating System ஆகும்...</div></div> </div> </div> </section> <sectionclass="section section-alt"> <divclass="section-inner"> <div class="s-lbl">Why TSTech Park</div> <h2 class="s-title">Everything You Needto Excel</h2> <p class="s-sub">A complete AI-poweredlearning ecosystem built for modern tech careers in India and beyond.</p><div class="feat-grid"> <div class="feat-card"><divclass="feat-ico"style="background:rgba(0,229,255,.1)"><i class="fasfa-robot"style="color:var(--accent)"></i></div><h3>AIChatbot — 4 Languages</h3><p>TechBot speaks English, Tamil, Hindi& Telugu. 24/7 FAQ support with content-specific knowledge and misbehaviourdetection.</p></div> <div class="feat-card"><divclass="feat-ico" style="background:rgba(124,77,255,.1)"><iclass="fas fa-play-circle"style="color:var(--accent2)"></i></div><h3>In-PageVideo Player</h3><p>Course videos open inside our site — no YouTuberedirects. YouTube embeds play in a full modal righthere.</p></div> <div class="feat-card"><divclass="feat-ico" style="background:rgba(0,230,118,.1)"><iclass="fas fa-certificate"style="color:var(--green)"></i></div><h3>VerifiedCertificates</h3><p>QR-verified, blockchain-backed certificatesshareable to LinkedIn, recognised by 200+ hiringpartners.</p></div> <div class="feat-card"><divclass="feat-ico"style="background:rgba(255,214,0,.1)"><i class="fasfa-trophy" style="color:var(--gold)"></i></div><h3>GamifiedLearning</h3><p>Earn XP, badges, climb leaderboards. Daily streaksand peer challenges keep you motivated.</p></div> <div class="feat-card"><divclass="feat-ico"style="background:rgba(255,61,113,.1)"><i class="fasfa-tasks"style="color:var(--accentr)"></i></div><h3>RichAssignments</h3><p>Real-world multi-subject assignments — design,code, research, data — with AI feedback within 24 hours.</p></div><div class="feat-card"><div class="feat-ico"style="background:rgba(0,229,255,.1)"><i class="fasfa-chart-line"style="color:var(--accent)"></i></div><h3>AIAnalytics</h3><p>Personalised insights on learning patterns, quizperformance and AI-powered study plan recommendations.</p></div></div> </div> </section> <sectionclass="cta-sect"> <div class="cta-inner"><h2>Ready to Start Your Tech Journey?</h2> <p>Join 50,000+students. First lesson free on every course.</p> <buttonclass="btn-hero bh-main"onclick="openAuth('signup')">Get Started Free <iclass="fas fa-arrow-right"></i></button> </div></section> </div> <!-- COURSES --> <divid="page-courses" class="page"> <divclass="pg-hdr"><divclass="pg-hdr-inner"><h2>Explore All Courses</h2><p>50+industry-aligned courses — choose your interest andenroll</p></div></div> <divclass="filter-bar"> <div class="filter-inner"><div class="sb"><i class="fasfa-search"></i><input type="text"id="courseSearch" placeholder="Search courses…"oninput="filterCourses()"/></div> <selectclass="fsel" id="catFilter" onchange="filterCourses()"><option value="">All Categories</option><option>Computer Science / IT</option><option>EmbeddedSystems & IoT</option><option>Electronics</option><option>Automotive</option><option>Data Science & AI</option><option>WebDevelopment</option> <option>Cloud &DevOps</option><option>Cybersecurity</option> </select><select class="fsel" id="levelFilter"onchange="filterCourses()"> <option value="">AllLevels</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select> <button class="fbtn active" id="sortBtn"onclick="toggleSort()"><i class="fasfa-sort"></i> Popular</button> </div> </div><div class="courses-wrap"> <div class="courses-res"id="coursesRes"></div> <divclass="courses-grid" id="coursesGrid"></div></div> </div> <!-- DASHBOARD --> <divid="page-dashboard" class="page"> <divclass="dash-layout"> <aside class="sidebar"><div class="sb-user"><div class="sb-av"id="sbAv">?</div><div><divclass="sb-name" id="sbName">Guest</div><divclass="sb-role">Student</div></div></div><div class="sb-section"> <divclass="sb-label">Main</div> <button class="sb-linkactive" onclick="switchDash(this,'overview')"><iclass="fas fa-th-large"></i>Overview</button><button class="sb-link"onclick="switchDash(this,'mycourses')"><i class="fasfa-book-open"></i>My Courses <span class="sb-badge"id="enrolledBadge">0</span></button> <buttonclass="sb-link"onclick="switchDash(this,'progress')"><i class="fasfa-chart-line"></i>Analytics</button> <buttonclass="sb-link" onclick="switchDash(this,'quizzes')"><iclass="fas fa-clipboard-check"></i>Quizzes &Tests</button> <button class="sb-link"onclick="switchDash(this,'assignments')"><i class="fasfa-tasks"></i>Assignments <span class="sb-badge"style="background:var(--gold);color:#000">3</span></button><button class="sb-link"onclick="switchDash(this,'certificates')"><i class="fasfa-certificate"></i>Certificates</button> </div><div class="sb-section"> <divclass="sb-label">Learning</div> <buttonclass="sb-link" onclick="switchDash(this,'notes')"><iclass="fas fa-sticky-note"></i>My Notes</button><button class="sb-link"onclick="switchDash(this,'wishlist')"><i class="fasfa-heart"></i>Wishlist</button> <buttonclass="sb-link"onclick="switchDash(this,'gamification')"><i class="fasfa-trophy"></i>Badges & XP</button> <buttonclass="sb-link" onclick="switchDash(this,'leaderboard')"><iclass="fas fa-ranking-star"></i>Leaderboard</button><button class="sb-link"onclick="switchDash(this,'schedule')"><i class="fasfa-calendar-alt"></i>Schedule</button> </div> <divclass="sb-section"> <divclass="sb-label">Account</div> <buttonclass="sb-link" onclick="showPage('profile')"><iclass="fas fa-user-circle"></i>My Profile</button><button class="sb-link"onclick="switchDash(this,'payments')"><i class="fasfa-credit-card"></i>Payments</button> <buttonclass="sb-link" onclick="switchDash(this,'settings')"><iclass="fas fa-cog"></i>Settings</button> <buttonclass="sb-link" style="color:var(--accentr)"onclick="doLogout()"><i class="fasfa-sign-out-alt"></i>Logout</button> </div></aside> <main class="dash-main"id="dashMain"></main> </div> </div> <!--FORUM --> <div id="page-forum" class="page"><div class="pg-hdr"><div class="pg-hdr-inner"><h2>CommunityForum</h2><p>Ask questions, share knowledge,collaborate</p></div></div> <divclass="forum-wrap"> <div class="forum-toolbar"><div class="sb" style="flex:1;min-width:160px"><iclass="fas fa-search"></i><input type="text"placeholder="Search…" oninput="filterForum(this.value)"style="width:100%"/></div> <selectclass="fsel"><option>AllTopics</option><option>Embedded</option><option>AI&ML</option><option>Projects</option><option>Career</option></select><button class="btn-sm btn-primary"onclick="openNewPost()"><i class="fasfa-plus"></i> Post</button> </div> <divclass="forum-tabs"> <button class="ftab active"onclick="setForumTab(this,'all')">All</button> <buttonclass="ftab"onclick="setForumTab(this,'questions')">Questions</button><button class="ftab"onclick="setForumTab(this,'projects')">Projects</button><button class="ftab"onclick="setForumTab(this,'announcements')">Announcements</button></div> <div id="forumPosts"></div> </div></div> <!-- LIVE --> <div id="page-live"class="page"> <div class="pg-hdr"><divclass="pg-hdr-inner"><h2>Live & UpcomingClasses</h2><p>Real-time sessions with expertinstructors</p></div></div> <divclass="l