ான கேள்வி! கொஞ்சம் விரிவாக கேட்கலாமா? உதாரணம்:<br>•"RTOS என்றால் என்ன?"<br>•"Embedded கட்டணம்எவ்வளவு?"<br>நான் 24/7 கிடைக்கிறேன்! ',}, hi:{ welcome:` नमस्ते! मैं<strong>TechBot</strong> हूं,TS Tech Park का AI शिक्षक!<br><br>कोर्स, फीस, बैच यातकनीकी विषयों के बारे मेंपूछें! `,faq:{ 'can bus':'<strong>CAN Bus</strong> Bosch का automotive ECU प्रोटोकॉल है।<br>• CAN FD: 8Mbps तक • Differentialsignaling<br><strong>Automotive Embedded</strong> कोर्स में सीखें ', 'fee':'<strong>कोर्स फीस:</strong><br>•Digital Electronics: ₹10,000<br>• Java/Python: ₹12,000–18,000<br>•ML/AI: ₹35,000–70,000<br>• Embedded: ₹22,000–60,000<br> EMI उपलब्ध', 'hello':'नमस्ते! मैं TechBot हूं। कोर्स, फीस,करियर के बारे मेंपूछें!', 'career':' Embedded: ₹3–30 LPA<br> AI/ML: ₹6–35LPA<br>Placement rate: 98%! ', 'thank':'धन्यवाद! पढ़ते रहें!', 'batch':' Automotive Embedded — 1 July 2026<br> Edge AI — 8 July2026<br> Early bird 15% छूट!', }, warn1:' कृपयासम्मानजनक बातचीत बनाए रखें।', warn2:' दूसरीचेतावनी: उचित भाषा काउपयोग करें।', warn3:' अनुचित सामग्री का पता चला।Support से संपर्क करें।', fallback:'अच्छा सवाल! थोड़ा विस्तार से बताएं? जैसे:<br>•"RTOS क्या है?"<br>•"Embedded कोर्स की फीस?"<br>मैं 24/7 उपलब्धहूं! ',}, te:{ welcome:` నమస్కారం! నేను<strong>TechBot</strong>, TS Tech Park AI ట్యూటర్!<br><br>కోర్సులు, ఫీజులు, బ్యాచ్‌లు లేదా సాంకేతికవిషయాల గురించి అడగండి! `,faq:{ 'hello':'నమస్కారం! నేను TechBot. కోర్సులు, ఫీజులు, కెరీర్ గురించి అడగండి!','fee':'<strong>కోర్సుఫీజులు:</strong><br>•Digital Electronics: ₹10,000<br>• Java/Python: ₹12,000–18,000<br>•ML/AI: ₹35,000–70,000<br>• Embedded: ₹22,000–60,000', 'career':' Embedded: ₹3–30 LPA<br> AI/ML: ₹6–35LPA<br>Placement: 98%! ', 'thank':'ధన్యవాదాలు! నేర్చుకోవడం కొనసాగించండి!', }, warn1:' దయచేసి గౌరవప్రదమైన సంభాషణ నిర్వహించండి.', warn2:' రెండవ హెచ్చరిక: సముచిత భాష ఉపయోగించండి.', warn3:' అనుచితమైన కంటెంట్ గుర్తించబడింది.', fallback:'మంచి ప్రశ్న! మరింతనిర్దిష్టంగా అడగగలరా? నేను 24/7 అందుబాటులో ఉన్నాను! ',}, }; const BAD=['stupid','idiot','fool','dumb','hate','kill','shutup','fuck','shit','bastard','bitch','die','suck','moron','crap','damnyou','useless','ugly','racist']; /* ═══SEEDED FORUM POSTS ═══ */const SEEDS=[ {id:1001,user:'Priya M',av:'PM',color:'#7c3aed',time:'2 hrsago',cat:'Question',catColor:'#e94560',title:'CAN bus vs LIN bus — when to choose?',text:'Working on dashboard ECU, confused aboutwhich protocol for body ECUs. Anyadvice?',likes:23,replies:8,tags:['CAN','LIN','Automotive'],type:'questions'},{id:1002,user:'Arjun V',av:'AV',color:'#0891b2',time:'4 hrs ago',cat:'Project',catColor:'#059669',title:'Builtlane detection with Edge AI on Jetson Nano!',text:'YOLO v8 + TensorRT on JetsonNano for 30fps lane detection. Happy to sharecode!',likes:87,replies:24,tags:['Edge AI','Jetson','YOLO'],type:'projects'},{id:1003,user:'Deepa K',av:'DK',color:'#dc2626',time:'6 hrsago',cat:'Question',catColor:'#f59e0b',title:'MISRA C beginnerresources?',text:'Starting automotive internship next month. Where to startwith MISRA C?',likes:14,replies:12,tags:['MISRA-C','Automotive','C'],type:'questions'},{id:1004,user:'TS Tech Park',av:'TS',color:'#e94560',time:'1 dayago',cat:'Announcement',catColor:'#0891b2',title:'New Batch: AutomotiveEmbedded — July 2026',text:'Applications open for July 1st batch. Limitedseats. 15% early bird discount!',likes:142,replies:35,tags:['Announcement','Batch'],type:'announcements'},{id:1005,user:'Karthik V',av:'KV',color:'#059669',time:'2 daysago',cat:'Project',catColor:'#059669',title:'Smart home with ESP32 + AWSIoT',text:'12 sensors on ESP32 with FreeRTOS tasks, publishing to AWS IoT viaMQTT. 2.1Waverage!',likes:64,replies:18,tags:['ESP32','AWS','IoT'],type:'projects'}, ];const LIVE_DATA={ live:[{title:'Edge AI: Neural NetworkQuantization',instructor:'Dr. Vijay R.',time:'LIVE NOW',attendees:142,emoji:' '}],upcoming:[ {title:'Automotive CAN FD — Advanced',instructor:'Mr. SureshK.',time:'Tomorrow 10 AM',attendees:89,emoji:' '}, {title:'Python forEmbedded Engineers',instructor:'Ms. Priya N.',time:'Tomorrow 3PM',attendees:203,emoji:' '}, {title:'RTOS DeepDive: FreeRTOS Tasks',instructor:'Mr. Karthik V.',time:'Thu 11AM',attendees:67,emoji:' '}, {title:'React + Node.jsFull Project',instructor:'Ms. Sneha L.',time:'Fri 4 PM',attendees:112,emoji:' '},], recordings:[ {title:'AUTOSAR Architecture Introduction',instructor:'Dr.Vijay R.',time:'Jun 5, 2026',emoji:' ',duration:'2h 14m'},{title:'Python ML: Scikit-learn Deep Dive',instructor:'Ms. Priya N.',time:'Jun3, 2026',emoji:' ',duration:'1h 48m'},{title:'Docker & Kubernetes for Beginners',instructor:'Mr. KarthikV.',time:'Jun 1, 2026',emoji:' ',duration:'3h 02m'}, ], };const ADMIN_USERS=[ {name:'Dr. VijayR.',email:'vijay@tstechpark.com',role:'Instructor',enrolled:0,status:'active',joined:'Aug2024'}, {name:'Mr. SureshK.',email:'suresh@tstechpark.com',role:'Instructor',enrolled:0,status:'active',joined:'Sep2024'}, {name:'ArjunV.',email:'arjun@example.com',role:'Student',enrolled:3,status:'active',joined:'Mar2025'}, {name:'DeepaK.',email:'deepa@example.com',role:'Student',enrolled:1,status:'pending',joined:'Jun2025'}, {name:'Karthik R.',email:'karthik@example.com',role:'Student',enrolled:5,status:'active',joined:'Jan2025'}, {name:'SnehaL.',email:'sneha@example.com',role:'Student',enrolled:2,status:'suspended',joined:'Apr2025'}, ]; /* ═══ INIT ═══ */document.addEventListener('DOMContentLoaded',()=>{ S.forumPosts=[...SEEDS];renderCourses(COURSES);renderForum();renderLive('live');renderAdminTable();renderAdminChart();renderAdminTop();renderAdminLog();renderNotifications();chatWelcome();loadStorage(); }); function loadStorage(){constu=localStorage.getItem('ts_user');if(u){S.user=JSON.parse(u);S.loggedIn=true;afterLogin();}conste=localStorage.getItem('ts_enrolled');if(e){S.enrolledCourses=JSON.parse(e);} }function saveEnrolled(){localStorage.setItem('ts_enrolled',JSON.stringify(S.enrolledCourses));}/* THEME */ function toggleTheme(){ constd=document.documentElement.dataset.theme==='dark';document.documentElement.dataset.theme=d?'light':'dark';document.getElementById('themeIcon').className=d?'fas fa-moon':'fas fa-sun';showToast(d?'Light mode on':'Dark mode on','info'); } /* PAGE NAV */ functionshowPage(n){document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));const pg=document.getElementById('page-'+n);if(pg)pg.classList.add('active');document.querySelectorAll('.nav-link').forEach(l=>l.classList.toggle('active',l.textContent.trim().toLowerCase().startsWith(n.toLowerCase())));S.currentPage=n;window.scrollTo(0,0);if(n==='dashboard'){if(!S.loggedIn){openAuth('login');return;}renderOverview();}if(n==='profile')renderProfilePage(); if(n==='admin')renderAdminTable(); } /*MOB MENU */ functiontoggleMob(){document.getElementById('mobMenu').classList.toggle('open');document.getElementById('mobOverlay').classList.toggle('open');}functioncloseMob(){document.getElementById('mobMenu').classList.remove('open');document.getElementById('mobOverlay').classList.remove('open');}functionsetMbn(el){document.querySelectorAll('.mbnav-btn').forEach(b=>b.classList.remove('active'));el.classList.add('active');}/* NOTIFICATIONS */ function renderNotifications(){ constp=document.getElementById('notifPanel'); const items=[{icon:'fa-robot',cls:'ni-p',title:'AI Quiz Ready',body:'Embedded quizgenerated',time:'2 min ago',unread:true}, {icon:'fa-certificate',cls:'ni-g',title:'CertificateEarned!',body:'Python Data Science — completed',time:'1 hr ago',unread:true},{icon:'fa-video',cls:'ni-b',title:'Live Class in 30 mins',body:'Edge AI: NeuralNetworks soon',time:'25 min ago',unread:false}, {icon:'fa-trophy',cls:'ni-y',title:'NewBadge!',body:'You earned "Code Ninja" ',time:'3 hrago',unread:false}, ]; p.innerHTML=`<divclass="ni-hdr"><spanstyle="font-weight:700;font-size:13px">Notifications</span><spanstyle="font-size:11px;color:var(--accent);cursor:pointer" onclick="markAllRead()">Markall read</span></div> ${items.map(n=>`<divclass="notif-item ${n.unread?'unread':''}"><divclass="ni-ico ${n.cls}"><i class="fas${n.icon}"></i></div><div><divstyle="font-size:12px;font-weight:700">${n.title}</div><divstyle="font-size:11px;color:var(--text2)">${n.body}</div><divstyle="font-size:10px;color:var(--text2)">${n.time}</div></div></div>`).join('')}<divstyle="padding:10px;text-align:center;font-size:11px;color:var(--accent);cursor:pointer;font-weight:600">Viewall</div>`; } functionmarkAllRead(){document.querySelectorAll('.notif-item.unread').forEach(i=>i.classList.remove('unread'));document.getElementById('notifBadge').style.display='none';showToast('Allread','success');} function toggleNotif(){S.notifOpen=!S.notifOpen;document.getElementById('notifPanel').classList.toggle('open',S.notifOpen);}document.addEventListener('click',e=>{if(S.notifOpen&&!e.target.closest('#notifPanel')&&!e.target.closest('#notifBtn')){S.notifOpen=false;document.getElementById('notifPanel').classList.remove('open');}});/* AUTH */ functionopenAuth(tab){document.getElementById('authModal').classList.add('active');switchAuth(tab);}function switchAuth(tab){document.getElementById('loginForm').style.display=tab==='login'?'block':'none';document.getElementById('signupForm').style.display=tab==='signup'?'block':'none';document.getElementById('loginTab').classList.toggle('active',tab==='login');document.getElementById('signupTab').classList.toggle('active',tab==='signup');} function setRole(btn){btn.closest('.role-sel').querySelectorAll('.role-btn').forEach(b=>b.classList.remove('active'));btn.classList.add('active');}function togglePw(id,btn){const i=document.getElementById(id);constp=i.type==='password';i.type=p?'text':'password';btn.innerHTML=p?'<iclass="fas fa-eye-slash"></i>':'<i class="fasfa-eye"></i>';} function chkPw(v){constel=document.getElementById('pwStr');if(!el)return;if(!v){el.className='pw-str';return;}if(v.length<6){el.className='pw-strweak';return;}if(v.length<10||!/[0-9]/.test(v)){el.className='pw-str medium';return;}el.className='pw-strstrong';} function doLogin(){ constemail=document.getElementById('loginEmail').value.trim(); constpass=document.getElementById('loginPass').value;if(!email||!pass){showToast('Please fill all fields','error');return;} constaccounts=JSON.parse(localStorage.getItem('ts_accounts')||'[]'); constfound=accounts.find(a=>a.email.toLowerCase()===email.toLowerCase()||a.username===email);constuser=found||{firstName:email.split('@')[0],lastName:'',email,phone:'',city:'',role:'Student',joinedDate:newDate().toLocaleDateString('en-IN',{month:'short',year:'numeric'}),xp:0,streak:1,hoursLearned:0,certificates:0,enrolledCount:0};finishLogin(user); } function doSignup(){ constfname=document.getElementById('regFname').value.trim(); const lname=document.getElementById('regLname').value.trim();const email=document.getElementById('regEmail').value.trim(); constphone=document.getElementById('regPhone').value.trim(); constcity=document.getElementById('regCity').value.trim(); constpass=document.getElementById('regPass').value; constpass2=document.getElementById('regPass2').value; constrole=document.querySelector('#signupForm.role-btn.active')?.textContent.trim().toLowerCase()||'student';if(!fname||!email||!phone||!pass){showToast('Fill required fields','error');return;}if(pass!==pass2){showToast('Passwords do not match','error');return;}if(pass.length<6){showToast('Password min 6 characters','error');return;}constuser={firstName:fname,lastName:lname,email,phone,city,role:role.includes('instructor')?'Instructor':'Student',joinedDate:newDate().toLocaleDateString('en-IN',{month:'short',year:'numeric'}),xp:0,streak:1,hoursLearned:0,certificates:0,enrolledCount:0,username:email.split('@')[0]};const accounts=JSON.parse(localStorage.getItem('ts_accounts')||'[]');accounts.push({...user,pass});localStorage.setItem('ts_accounts',JSON.stringify(accounts));finishLogin(user);showToast(`Welcome, ${fname}! `,'success'); } functionfinishLogin(user){S.user=user;S.loggedIn=true;localStorage.setItem('ts_user',JSON.stringify(user));closeModal('authModal');afterLogin();showPage('dashboard');if(!user.firstName.includes('@'))showToast(`Welcome back, ${user.firstName}! `,'success');} function afterLogin(){ const u=S.user;const init=getInit(u);document.getElementById('userAvBtn').style.display='flex';document.getElementById('userAvInit').textContent=init;document.getElementById('guestButtons').style.display='none'; document.getElementById('sbAv').textContent=init;document.getElementById('sbName').textContent=getDisplayName(u); conste=localStorage.getItem('ts_enrolled');if(e){S.enrolledCourses=JSON.parse(e);}document.getElementById('enrolledBadge').textContent=S.enrolledCourses.length;renderProfilePage(); } function doLogout(){S.loggedIn=false;S.user=null;S.enrolledCourses=[];localStorage.removeItem('ts_user');document.getElementById('userAvBtn').style.display='none';document.getElementById('guestButtons').style.display='flex';document.getElementById('sbAv').textContent='?';document.getElementById('sbName').textContent='Guest';showPage('home');showToast('Logged out','info'); } functiongetInit(u){if(!u)return'?';return((u.firstName||'').charAt(0)+(u.lastName||'').charAt(0)).toUpperCase()||(u.email||'?').charAt(0).toUpperCase();}functiongetDisplayName(u){if(!u)return'Guest';return[u.firstName,u.lastName].filter(Boolean).join('').trim()||u.email||'User';} functionhandleOverlay(e,id){if(e.target===e.currentTarget)closeModal(id);} functioncloseModal(id){document.getElementById(id).classList.remove('active');} /*COURSES */ function renderCourses(data){ constgrid=document.getElementById('coursesGrid'); constres=document.getElementById('coursesRes'); if(res)res.textContent=`Showing${data.length} course${data.length!==1?'s':''}`; if(!grid)return;if(!data.length){grid.innerHTML=`<div class="empty-state"style="grid-column:1/-1"><i class="fasfa-search"></i><p>No courses match yourfilters.</p><button class="btn-enroll"onclick="clearFilters()">ClearFilters</button></div>`;return;} grid.innerHTML=data.map(c=>`<div class="cc" onclick="openCourseModal(${c.id})"><div class="cc-thumb"style="background:linear-gradient(135deg,${c.bg}22,${c.bg}44)"><span>${c.emoji}</span> ${c.badge?`<span class="cc-badgebadge-${c.badge}">${c.badge.toUpperCase()}</span>`:''} <buttonclass="cc-wish ${S.wishlist.has(c.id)?'active':''}"onclick="event.stopPropagation();toggleWish(${c.id},this)"><iclass="fas fa-heart"></i></button> </div><div class="cc-body"> <divclass="cc-cat">${c.cat}</div> <divclass="cc-title">${c.title}</div> <div class="cc-desc">${c.desc.substring(0,82)}…</div><div class="cc-meta"><span><i class="fasfa-clock"></i>${c.hrs}h</span><span><iclass="fas fa-signal"></i>${c.level}</span><span><iclass="fasfa-users"></i>${c.students.toLocaleString()}</span></div><div class="cc-rating"><span class="stars">${'★'.repeat(Math.floor(c.rating))}</span><strong>${c.rating}</strong></div><div class="cc-footer"><div class="cc-price">₹${c.price.toLocaleString()}<span class="cc-old">₹${Math.floor(c.price*1.2).toLocaleString()}</span></div><buttonclass="btn-enroll"onclick="event.stopPropagation();enrollCourse(${c.id})">EnrollNow</button></div> </div> </div>`).join(''); } functionfilterCourses(){ constq=(document.getElementById('courseSearch')?.value||'').toLowerCase(); constcat=document.getElementById('catFilter')?.value||''; constlevel=document.getElementById('levelFilter')?.value||''; letdata=COURSES.filter(c=>(!q||c.title.toLowerCase().includes(q)||c.cat.toLowerCase().includes(q))&&(!cat||c.cat===cat)&&(!level||c.level===level));if(S.sortMode==='popular')data.sort((a,b)=>b.students-a.students);if(S.sortMode==='price_asc')data.sort((a,b)=>a.price-b.price);if(S.sortMode==='price_desc')data.sort((a,b)=>b.price-a.price);if(S.sortMode==='rating')data.sort((a,b)=>b.rating-a.rating);renderCourses(data); } function toggleSort(){ constmodes=['popular','rating','price_asc','price_desc'];constlabels=['Popular','Rating','Price ↑','Price ↓']; const idx=(modes.indexOf(S.sortMode)+1)%modes.length;S.sortMode=modes[idx];document.getElementById('sortBtn').innerHTML=`<i class="fasfa-sort"></i> ${labels[idx]}`;filterCourses(); } functionclearFilters(){document.getElementById('courseSearch').value='';document.getElementById('catFilter').value='';document.getElementById('levelFilter').value='';renderCourses(COURSES);}functiontoggleWish(id,btn){if(S.wishlist.has(id)){S.wishlist.delete(id);btn.classList.remove('active');showToast('Removedfrom wishlist','info');}else{S.wishlist.add(id);btn.classList.add('active');showToast('Addedto wishlist ','success');}} function enrollCourse(id){if(!S.loggedIn){openAuth('login');return;} constc=COURSES.find(x=>x.id===id); if(!S.enrolledCourses.includes(id)){S.enrolledCourses.push(id);if(S.user)S.user.enrolledCount=(S.user.enrolledCount||0)+1; saveEnrolled();document.getElementById('enrolledBadge').textContent=S.enrolledCourses.length;} closeModal('courseModal');showToast(`Enrolled in ${c.title}! `,'success');} /* VIDEO PLAYER — embedded in page */ functionopenVideoPlayer(ytId,title,desc){document.getElementById('videoModalBody').innerHTML=` <divclass="vid-wrap"><iframesrc="https://www.youtube.com/embed/${ytId}?autoplay=1&rel=0"allow="accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture"allowfullscreen></iframe></div> <divclass="vid-info"><h3>${title}</h3><p>${desc||'TSTech Park — Course Content'}</p></div>`;document.getElementById('videoModal').classList.add('active'); } functionstopVideo(){document.getElementById('videoModalBody').innerHTML='';} functionopenCourseModal(id){ const c=COURSES.find(x=>x.id===id);if(!c)return;document.getElementById('courseModalBody').innerHTML=` <divclass="cm-thumb"style="background:linear-gradient(135deg,${c.bg}22,${c.bg}55)"><span>${c.emoji}</span> <div class="cm-play"onclick="openVideoPlayer('${c.videos[0].yt}','${c.videos[0].title}','${c.desc}')"><iclass="fas fa-play"></i></div> </div> <divclass="cm-body"> <div style="display:flex;gap:7px;margin-bottom:8px;flex-wrap:wrap"><span class="cc-cat"style="margin:0">${c.cat}</span> <spanstyle="background:${c.bg}22;color:${c.bg};padding:2px8px;border-radius:4px;font-size:9px;font-weight:700">${c.level}</span>${c.badge?`<span class="cc-badge badge-${c.badge}"style="position:static">${c.badge.toUpperCase()}</span>`:''}</div> <div class="cm-title">${c.title}</div><divstyle="display:flex;align-items:center;gap:6px;margin-bottom:9px"><spanclass="stars">${'★'.repeat(Math.floor(c.rating))}</span><strong>${c.rating}</strong><spanstyle="color:var(--text2);font-size:11px">(${c.students.toLocaleString()}students)</span></div> <div class="cm-desc">${c.desc}</div><div class="cm-tabs"> <button class="cm-tabactive" onclick="cmTab(this,'cmCur')"> Curriculum</button> <button class="cm-tab"onclick="cmTab(this,'cmVid')"> Videos</button><button class="cm-tab" onclick="cmTab(this,'cmPay')"> Enroll</button> <button class="cm-tab"onclick="cmTab(this,'cmInfo')"> Info</button></div> <div id="cmCur" class="cm-tab-bodyactive"> ${c.curriculum.map((item,i)=>`<divclass="cur-item"><i class="fasfa-${i===0?'play-circle':'lock'}"></i><span>${item}</span>${i===0?'<spanstyle="margin-left:auto;font-size:9px;color:var(--green);font-weight:700">FREEPREVIEW</span>':''}</div>`).join('')} </div> <divid="cmVid" class="cm-tab-body"> <pstyle="font-size:11px;color:var(--text2);margin-bottom:10px"> Videos open <strong>right here</strong> — no YouTube redirect.Curated course content.</p> ${c.videos.map((v,i)=>` <divclass="cur-item"onclick="openVideoPlayer('${v.yt}','${v.title}','${c.desc}')"><divstyle="width:48px;height:32px;border-radius:6px;background:${c.bg}22;display:flex;align-items:center;justify-content:center;flex-shrink:0"><iclass="fas fa-play-circle"style="color:${c.bg};font-size:18px"></i></div><div><divstyle="font-weight:600;font-size:12px">${v.title}</div><divstyle="font-size:10px;color:var(--text2)">Lesson${i+1}</div></div> <button class="play-btn-sm"onclick="event.stopPropagation();openVideoPlayer('${v.yt}','${v.title}','')"><iclass="fas fa-play"></i>Play</button></div>`).join('')} </div> <div id="cmPay"class="cm-tab-body"> <divstyle="font-size:1.6rem;font-weight:800;color:var(--accent);margin-bottom:4px">₹${c.price.toLocaleString()}</div><divstyle="font-size:11px;color:var(--text2);margin-bottom:12px">Lifetimeaccess • Certificate • All updates free</div> <div class="pay-opts"><label class="pay-opt sel"><input type="radio"name="pm" checked style="margin-right:4px"> UPI</label> <label class="pay-opt"><inputtype="radio" name="pm"style="margin-right:4px"> Card</label><label class="pay-opt"><input type="radio"name="pm" style="margin-right:4px"> Net Banking</label> <label class="pay-opt"><inputtype="radio" name="pm"style="margin-right:4px"> EMI</label><label class="pay-opt"><input type="radio"name="pm" style="margin-right:4px"> Cash</label> </div> <button class="btn-fullbtn-accent" style="margin-top:8px"onclick="enrollCourse(${c.id});showToast('Payment successful! Courseunlocked ','success')">Pay & Enroll —₹${c.price.toLocaleString()}</button> <divstyle="text-align:center;margin-top:8px;font-size:11px;color:var(--text2)"> Secure · 30-day money-back</div> </div> <divid="cmInfo" class="cm-tab-body"> <divstyle="display:grid;grid-template-columns:1fr1fr;gap:10px;font-size:12px"> <div><strong><i class="fasfa-clock"style="color:var(--accent);margin-right:3px"></i>Duration</strong><divstyle="color:var(--text2);margin-top:2px">${c.hrs}hours</div></div> <div><strong><i class="fasfa-signal"style="color:var(--accent);margin-right:3px"></i>Level</strong><divstyle="color:var(--text2);margin-top:2px">${c.level}</div></div><div><strong><i class="fas fa-users"style="color:var(--accent);margin-right:3px"></i>Students</strong><divstyle="color:var(--text2);margin-top:2px">${c.students.toLocaleString()}</div></div><div><strong><i class="fas fa-star"style="color:var(--gold);margin-right:3px"></i>Rating</strong><divstyle="color:var(--text2);margin-top:2px">${c.rating}/5.0</div></div><div><strong><i class="fas fa-certificate"style="color:var(--accent);margin-right:3px"></i>Certificate</strong><divstyle="color:var(--text2);margin-top:2px">Yes,QR-verified</div></div> <div><strong><iclass="fas fa-language"style="color:var(--accent);margin-right:3px"></i>Language</strong><divstyle="color:var(--text2);margin-top:2px">English /Tamil</div></div> </div> </div> </div>`;document.getElementById('courseModal').classList.add('active'); } functioncmTab(btn,id){ const b=btn.closest('.cm-body'); b.querySelectorAll('.cm-tab').forEach(t=>t.classList.remove('active'));b.querySelectorAll('.cm-tab-body').forEach(t=>t.classList.remove('active'));btn.classList.add('active');document.getElementById(id).classList.add('active');} /* DASHBOARD */ function switchDash(btn,sec){document.querySelectorAll('.sb-link').forEach(l=>l.classList.remove('active'));if(btn)btn.classList.add('active'); constfns={overview:renderOverview,mycourses:renderMyCourses,progress:renderProgress,quizzes:renderQuizSel,assignments:renderAssignments,certificates:renderCerts,notes:renderNotes,wishlist:renderWishlist,gamification:renderGameplay,leaderboard:renderLB,schedule:renderSchedule,payments:renderPayments,settings:renderSettings};(fns[sec]||renderOverview)(); } function renderOverview(){if(!S.loggedIn){openAuth('login');return;} const u=S.user;constnm=getDisplayName(u); const myC=S.enrolledCourses.map(id=>COURSES.find(c=>c.id===id)).filter(Boolean).slice(0,4);const progs=[72,45,88,30]; document.getElementById('dashMain').innerHTML=`<div class="dash-hdr"> <div><h2>Welcome back,${nm}! </h2><p>You have 3 assignmentsdue and 1 live class today.</p></div> <divstyle="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><div style="display:flex;align-items:center;gap:5px;background:rgba(255,214,0,.1);border:1pxsolid rgba(255,214,0,.2);border-radius:8px;padding:6px11px;font-size:11px;color:var(--gold)"><i class="fasfa-fire"></i>${u.streak||1}-day streak!</div> <buttonclass="btn-sm btn-primary"onclick="switchDash(null,'quizzes')"><i class="fasfa-robot"></i> Quiz</button> </div> </div><div class="stats-grid"> <div class="stat-cardsc1"><div class="sc-ico"><i class="fasfa-book-open"></i></div><divclass="sc-val">${S.enrolledCourses.length}</div><divclass="sc-lbl">Enrolled Courses</div><divclass="sc-chg">Choose from Courses page</div></div><div class="stat-card sc2"><divclass="sc-ico"><i class="fasfa-clock"></i></div><divclass="sc-val">${u.hoursLearned||0}h</div><divclass="sc-lbl">Hours Learned</div><divclass="sc-chg">Track via Resume</div></div> <divclass="stat-card sc3"><div class="sc-ico"><iclass="fas fa-star"></i></div><divclass="sc-val">${u.xp||0}</div><divclass="sc-lbl">XP Points</div><divclass="sc-chg">Earn by completing tasks</div></div><div class="stat-card sc4"><divclass="sc-ico"><i class="fasfa-certificate"></i></div><divclass="sc-val">${u.certificates||0}</div><divclass="sc-lbl">Certificates</div><divclass="sc-chg">Complete courses to earn</div></div></div> <div class="dash-g2"> <divclass="dash-card"> <div class="dc-title">ContinueLearning <a onclick="switchDash(null,'mycourses')">Viewall</a></div> ${myC.length===0?`<divclass="empty-state" style="padding:1.5rem"><iclass="fas fa-book"></i><pstyle="margin-bottom:8px">No courses enrolledyet.</p><button class="btn-enroll"onclick="showPage('courses')">BrowseCourses</button></div>`: myC.map((c,i)=>`<divclass="enr-item"><div class="enr-ico" style="background:${c.bg}22">${c.emoji}</div><divstyle="flex:1;min-width:0"><divclass="enr-name">${c.title}</div><divclass="enr-prog"><div class="mb"><div class="mf"style="width:${progs[i]||25}%"></div></div>${progs[i]||25}%</div></div><buttonclass="btn-resume"onclick="openVideoPlayer('${c.videos[0].yt}','${c.videos[0].title}','')">Resume</button></div>`).join('')}${myC.length===0?'':myC.length>0&&S.enrolledCourses.length===0?`<divstyle="margin-top:9px;padding:9px;background:rgba(0,229,255,.06);border-radius:8px;font-size:11px;color:var(--text2);text-align:center">Enrollfrom <a onclick="showPage('courses')"style="color:var(--accent);cursor:pointer">Courses page</a></div>`:''}</div> <div> <div class="dash-card"style="margin-bottom:12px"> <divclass="dc-title">Recent Activity</div>${[{icon:'fa-check-circle',cls:'ad-g',title:'Completed: CAN Bus Module',time:'2hrs ago'},{icon:'fa-trophy',cls:'ad-y',title:'Badge: Code Ninja',time:'5 hrsago'},{icon:'fa-clipboard-check',cls:'ad-b',title:'Quiz: 8/10 onRTOS',time:'Yesterday'},{icon:'fa-play',cls:'ad-p',title:'Started: Edge AIModule 4',time:'2 days ago'}].map(a=>`<divclass="act-item"><div class="act-dot${a.cls}"><i class="fas ${a.icon}"style="font-size:10px"></i></div><div><divclass="act-title">${a.title}</div><divclass="act-time">${a.time}</div></div></div>`).join('')}</div> <div class="streak-card"> <divstyle="font-size:10px;color:var(--text2);margin-bottom:2px"> STREAK</div> <divclass="streak-num">${u.streak||1}</div> <divstyle="font-size:11px;color:var(--text2)">days in arow!</div> <divclass="week-dots">${['M','T','W','T','F','S','S'].map((d,i)=>`<divclass="wd${i<5?'wd-done':i===5?'wd-today':'wd-future'}">${d}</div>`).join('')}</div></div> </div> </div>`; } function renderMyCourses(){ constmyC=S.enrolledCourses.map(id=>COURSES.find(c=>c.id===id)).filter(Boolean);document.getElementById('dashMain').innerHTML=` <divclass="dash-hdr"><div><h2>My Courses</h2><p>${myC.length}enrolled</p></div><button class="btn-sm btn-primary"onclick="showPage('courses')"><i class="fasfa-plus"></i> Browse More</button></div>${myC.length===0?`<div class="empty-state"><iclass="fas fa-book-open"></i><p>No courses yet. Browseand enroll!</p><button class="btn-enroll"onclick="showPage('courses')">Browse Courses</button></div>`:`<divstyle="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:13px">${myC.map(c=>`<div class="cc" onclick="openVideoPlayer('${c.videos[0].yt}','${c.videos[0].title}','')"><div class="cc-thumb"style="background:linear-gradient(135deg,${c.bg}22,${c.bg}44);height:100px">${c.emoji}</div><div class="cc-body"><div class="cc-title">${c.title}</div><div class="prog-bar" style="margin:9px 03px"><div class="prog-fill"style="width:${Math.floor(20+Math.random()*70)}%"></div></div><button class="btn-enroll"style="width:100%;margin-top:9px"><i class="fasfa-play"></i> Resume</button></div></div>`).join('')} </div>`}`; } function renderProgress(){document.getElementById('dashMain').innerHTML=` <divclass="dash-hdr"><div><h2>Analytics</h2><p>Yourlearning performance</p></div></div> <divclass="dash-geq"> <div class="dash-card"> <divclass="dc-title">Weekly Hours</div> <divstyle="display:flex;align-items:flex-end;gap:5px;height:80px;margin-top:9px">${[3,5,4,7,6,8,5].map((h,i)=>`<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:3px"><spanstyle="font-size:9px;color:var(--text2)">${h}h</span><divstyle="width:100%;height:${h*9}px;background:linear-gradient(totop,var(--accent),var(--accent2));border-radius:2px 2px 00"></div><spanstyle="font-size:9px;color:var(--text2)">${['M','T','W','T','F','S','S'][i]}</span></div>`).join('')}</div> </div> <div class="dash-card"> <divclass="dc-title">Quiz Scores</div> ${[{s:'EmbeddedC',sc:90},{s:'RTOS',sc:80},{s:'CAN Protocol',sc:95},{s:'PythonML',sc:75}].map(q=>`<div style="margin-bottom:9px"><divstyle="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px"><span>${q.s}</span><strong>${q.sc}%</strong></div><divclass="prog-bar"><div class="prog-fill"style="width:${q.sc}%"></div></div></div>`).join('')}</div> </div> <div class="dash-card"> <divclass="dc-title"> AI Insights</div><div style="background:rgba(124,77,255,.08);border:1px solidrgba(124,77,255,.2);border-radius:10px;padding:14px;display:flex;gap:11px"><div style="font-size:1.5rem;flex-shrink:0"> </div><div><divstyle="font-weight:700;margin-bottom:6px;font-size:13px">TechBotAnalysis for ${getDisplayName(S.user)}</div> <pstyle="font-size:12px;color:var(--text2);line-height:1.7">You'reexcelling in Embedded C (90th percentile). CAN protocol score is exceptional at95%. Recommended next: <strong>FreeRTOS Semaphores & Queues (Module6)</strong> — estimated 4 hours.</p></div> </div></div>`; } function renderQuizSel(){document.getElementById('dashMain').innerHTML=` <divclass="dash-hdr"><div><h2>Quizzes &Tests</h2><p>Multi-subject AI-generatedquizzes</p></div></div> <divstyle="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:11px;margin-bottom:18px">${Object.keys(QB).map(topic=>`<div class="dash-card"style="cursor:pointer;text-align:center;transition:var(--tr)"onclick="startQuiz('${topic}')"onmouseover="this.style.borderColor='var(--accent)'"onmouseout="this.style.borderColor='var(--border)'"> <divstyle="font-size:1.8rem;margin-bottom:8px">${{'Embedded Systems':' ','ComputerScience':' ','AI & Data Science':' ','Electronics':' '}[topic]}</div><divstyle="font-weight:700;font-size:12px;margin-bottom:3px">${topic}</div><divstyle="font-size:10px;color:var(--text2)">${QB[topic].length}questions</div> <button class="btn-enroll"style="margin-top:10px;width:100%">Start Quiz</button></div>`).join('')} </div> <div class="dash-card"><div class="dc-title">Quiz History</div> ${[{s:'EmbeddedSystems',sc:85,d:'Today'},{s:'Computer Science',sc:90,d:'Yesterday'},{s:'AI& Data Science',sc:70,d:'2 days ago'}].map(h=>`<divstyle="display:flex;align-items:center;justify-content:space-between;padding:9px0;border-bottom:1px solid var(--border)"><div><divstyle="font-weight:600;font-size:12px">${h.s}</div><divstyle="font-size:10px;color:var(--text2)">${h.d}</div></div><spanstyle="font-weight:800;font-size:14px;color:${h.sc>=80?'var(--green)':h.sc>=60?'var(--gold)':'var(--accentr)'}">${h.sc}%</span></div>`).join('')}</div>`; } function startQuiz(topic){ const qs=QB[topic]||QB['EmbeddedSystems']; let cur=0,score=0,answered=false,timerSec=60; if(S.quizTimer)clearInterval(S.quizTimer);function render(){ if(cur>=qs.length){ clearInterval(S.quizTimer); constpct=Math.round(score/qs.length*100);document.getElementById('dashMain').innerHTML=`<divstyle="max-width:520px;margin:3rem auto;text-align:center"><div style="font-size:3rem;margin-bottom:14px">${pct>=85?' ':pct>=65?' ':' '}</div><h2>Quiz Complete!</h2> <divstyle="font-size:2.5rem;font-weight:800;color:${pct>=85?'var(--green)':pct>=65?'var(--gold)':'var(--accentr)'};margin:12px0">${score}/${qs.length}</div> <p style="color:var(--text2)">Score:${pct}% · ${pct>=85?'Excellent!':pct>=65?'Good effort!':'Keeppractising!'}</p> <divstyle="display:flex;gap:9px;justify-content:center;margin-top:18px;flex-wrap:wrap"><button class="btn-quiz bq-p"onclick="startQuiz('${topic}')">Try Again</button><button class="btn-quiz bq-s" onclick="renderQuizSel()">AllQuizzes</button> <button class="btn-quiz bq-s"onclick="switchDash(null,'overview')">Dashboard</button></div> ${pct===100?'<div style="margin-top:14px;background:rgba(0,230,118,.08);border:1pxsolidrgba(0,230,118,.25);border-radius:9px;padding:12px"><strong> Perfect! +100 XP!</strong></div>':''} </div>`;return; } constq=qs[cur];timerSec=60; document.getElementById('dashMain').innerHTML=` <divclass="dash-hdr"><div><h2>${topic}Quiz</h2><p>Q ${cur+1} of ${qs.length}</p></div><divclass="timer-badge"><i class="fasfa-clock"></i><spanid="td">1:00</span></div></div> <divclass="quiz-wrap"> <div class="dash-card"style="margin-bottom:11px"> <divstyle="display:flex;justify-content:space-between;font-size:12px;font-weight:600;margin-bottom:9px"><span>Progress</span><span>${cur+1}/${qs.length}· Score: ${score}</span></div> <divclass="prog-bar"><div class="prog-fill"style="width:${(cur/qs.length*100)}%"></div></div></div> <div class="q-card"> <divclass="q-num">Question ${cur+1}</div> <divclass="q-text">${q.q}</div> <divclass="opts-list">${q.o.map((opt,i)=>`<divclass="opt" id="op${i}"onclick="selOpt(${i},${q.a})"><divclass="opt-l">${String.fromCharCode(65+i)}</div><span>${opt}</span></div>`).join('')}</div></div> <div class="quiz-nav"> <buttonclass="btn-quiz bq-s"onclick="startQuiz('${topic}')"><i class="fasfa-redo"></i> Restart</button> <buttonclass="btn-quiz bq-p" id="nextBtn" disabledonclick="nextQ()">${cur+1<qs.length?'Next <i class="fasfa-arrow-right"></i>':'Finish <i class="fasfa-flag-checkered"></i>'}</button> </div></div>`; S.quizTimer=setInterval(()=>{timerSec--;constel=document.getElementById('td');if(el)el.textContent=`${Math.floor(timerSec/60)}:${String(timerSec%60).padStart(2,'0')}`;if(timerSec<=0){clearInterval(S.quizTimer);nextQ();}},1000);window.selOpt=(i,a)=>{if(answered)return;answered=true;clearInterval(S.quizTimer);document.querySelectorAll('.opt').forEach(o=>o.style.pointerEvents='none');document.getElementById('op'+i).classList.add(i===a?'correct':'wrong');if(i!==a)document.getElementById('op'+a).classList.add('correct');if(i===a)score++;document.getElementById('nextBtn').disabled=false;};window.nextQ=()=>{cur++;answered=false;render();}; } render(); } functionrenderAssignments(){ const tasks=[ {title:'Design CAN Bus message matrix forvehicle ECU network',course:'Automotive Embedded',due:'Jun 15,2026',status:'pending',pts:50,type:'fa-draw-polygon'}, {title:'ImplementFreeRTOS mutex for shared resource in C',course:'RTOS',due:'Jun 18,2026',status:'pending',pts:40,type:'fa-code'}, {title:'Python data analysis onEV telemetry dataset',course:'Python for Data Science',due:'Jun 12,2026',status:'submitted',pts:45,type:'fa-chart-bar'}, {title:'Arduino smarthome automation project report',course:'ESP32 Development',due:'Jun 8, 2026',status:'graded',pts:50,grade:'92/100',type:'fa-file-alt'},{title:'Analyse IEEE paper on Edge AI — 500-word summary',course:'EdgeAI',due:'Jun 20, 2026',status:'pending',pts:30,type:'fa-book-open'},{title:'React CRUD app with authentication',course:'Web Development',due:'Jun22, 2026',status:'pending',pts:60,type:'fa-code'}, {title:'Traffic lightcontroller state machine in Verilog',course:'Digital Electronics',due:'Jun 25,2026',status:'pending',pts:35,type:'fa-draw-polygon'}, {title:'Design AUTOSAR SWCfor body control module',course:'Automotive Embedded',due:'Jun 28,2026',status:'pending',pts:55,type:'fa-cogs'}, {title:'Implement priorityinversion demo with FreeRTOS',course:'RTOS',due:'Jun 30,2026',status:'pending',pts:45,type:'fa-code'}, ]; document.getElementById('dashMain').innerHTML=`<divclass="dash-hdr"><div><h2>Assignments</h2><p>${tasks.filter(t=>t.status==='pending').length}pending</p></div></div> ${tasks.map(a=>`<div class="dash-card"style="margin-bottom:10px"> <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:9px;flex-wrap:wrap"><divstyle="display:flex;align-items:flex-start;gap:9px;flex:1"><div class="act-dotad-${a.status==='graded'?'g':a.status==='submitted'?'b':'p'}"style="flex-shrink:0;margin-top:1px"><i class="fas${a.type}" style="font-size:10px"></i></div><div><divstyle="font-weight:700;font-size:13px;margin-bottom:3px">${a.title}</div><divstyle="font-size:10px;color:var(--text2)">${a.course} · Due:${a.due} · ${a.pts} pts</div></div> </div> <spanclass="s-pill${a.status==='graded'?'sp-active':a.status==='submitted'?'sp-pending':'sp-susp'}">${a.status.toUpperCase()}</span></div> <divstyle="display:flex;gap:6px;margin-top:10px;flex-wrap:wrap;align-items:center">${a.status==='graded'?`<spanstyle="font-weight:800;font-size:13px;color:var(--green)">Grade:${a.grade}</span><button class="abt ab-v"onclick="showToast('AI feedback opening…','info')"><i class="fasfa-robot"></i> AI Feedback</button>`:a.status==='submitted'?`<span style="font-size:11px;color:var(--text2)"><iclass="fas fa-clock"></i> Awaitingreview</span><button class="abt ab-v"onclick="showToast('Openingsubmission…','info')">View</button>`: `<button class="abtab-e" onclick="showToast('Editor opened','info')"><iclass="fas fa-upload"></i> Submit</button><buttonclass="abt ab-v" onclick="showToast('AI hint generated! CheckTechBot ','info')"><i class="fasfa-robot"></i> AI Hint</button>`} </div></div>`).join('')}`; } function renderCerts(){ const u=S.user;constmyC=S.enrolledCourses.map(id=>COURSES.find(c=>c.id===id)).filter(Boolean);const done=[{course:'Python for Data Science',date:'March2025',id:'TS-2025-PDS-8291'},{course:'Embedded Systems Fundamentals',date:'May2025',id:'TS-2025-ESF-4472'}]; document.getElementById('dashMain').innerHTML=`<div class="dash-hdr"><div><h2>Certificates</h2><p>VerifiedQR-backed credentials</p></div></div> <divstyle="display:grid;grid-template-columns:repeat(auto-fill,minmax(380px,1fr));gap:15px">${done.map(cert=>`<div class="cert-card"><divclass="cert-org">TS TECH PARK</div><divclass="cert-sub">A Group of TS Institutions</div><divclass="cert-lbl">Certificate of Completion</div><divclass="cert-name">${getDisplayName(u)}</div><divstyle="font-size:12px;color:rgba(255,255,255,.55);margin-bottom:4px">hassuccessfully completed</div><divclass="cert-course">${cert.course}</div><divclass="cert-date">Awarded: ${cert.date} · ID:${cert.id}</div><div class="cert-foot"><divclass="qr-box"><i class="fas fa-qrcode"style="font-size:20px;color:var(--primary)"></i></div><div><divstyle="font-size:10px;margin-bottom:2px">Scan toverify</div><divstyle="font-size:9px;opacity:.4">${cert.id}</div></div><divstyle="margin-left:auto;display:flex;gap:4px"><buttononclick="showToast('PDF downloading!','success')"style="padding:5px9px;background:var(--gold);color:#4a2e00;border:none;border-radius:5px;font-size:10px;font-weight:700;cursor:pointer"><iclass="fas fa-download"></i></button><buttononclick="showToast('LinkedIn link copied!','info')"style="padding:5px 9px;background:rgba(255,255,255,.1);color:#fff;border:1pxsolidrgba(255,255,255,.2);border-radius:5px;font-size:10px;cursor:pointer"><iclass="fabfa-linkedin"></i></button></div></div></div>`).join('')}${myC.map(c=>`<div class="dash-card"style="display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;min-height:160px;border-style:dashed"><iclass="fas fa-lock"style="font-size:1.5rem;color:var(--text2);margin-bottom:9px;opacity:.3"></i><divstyle="font-weight:700;font-size:13px;margin-bottom:3px">${c.title}</div><divstyle="font-size:11px;color:var(--text2)">Complete course tounlock</div><div class="prog-bar"style="width:160px;margin-top:9px"><divclass="prog-fill" style="width:35%"></div></div></div>`).join('')}</div>`; } function renderNotes(){ const seed=[{title:'CAN Bus KeyPoints',course:'Automotive Embedded',note:'• Differential signaling\n• CAN FD:8 Mbps\n• Multi-master\n• CSMA/CD',color:'#7c4dff',date:'Today'},{title:'RTOSTask States',course:'Embedded Systems',note:'Running → Ready → Blocked →Suspended\nvTaskDelay() vs vTaskDelayUntil()',color:'#00e5ff',date:'Yesterday'},...S.notes];document.getElementById('dashMain').innerHTML=` <divclass="dash-hdr"><div><h2>MyNotes</h2><p>${seed.length} notes</p></div><buttonclass="btn-sm btn-primary" onclick="addNote()"><iclass="fas fa-plus"></i> New</button></div><divstyle="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px">${seed.map((n,i)=>`<div class="dash-card"style="border-top:2px solid ${n.color}"><divstyle="font-weight:700;margin-bottom:2px;font-size:13px">${n.title}</div><divstyle="font-size:10px;color:var(--text2);margin-bottom:9px">${n.course}· ${n.date}</div><prestyle="font-size:11px;font-family:'Inter',sans-serif;color:var(--text2);white-space:pre-wrap;line-height:1.7">${n.note}</pre><divstyle="display:flex;gap:6px;margin-top:9px"><buttonclass="abt ab-e" onclick="showToast('Editoropened','info')">Edit</button><button class="abtab-d"onclick="S.notes.splice(${i-2},1);renderNotes()">Delete</button></div></div>`).join('')}</div>`; } function addNote(){const t=prompt('Note title:');constn=prompt('Content:');if(t&&n){S.notes.unshift({title:t,course:'General',note:n,color:'#00e5ff',date:'Justnow'});renderNotes();showToast('Saved!','success');}} functionrenderWishlist(){ const list=COURSES.filter(c=>S.wishlist.has(c.id));document.getElementById('dashMain').innerHTML=`<divclass="dash-hdr"><div><h2>Wishlist</h2><p>${list.length}courses saved</p></div></div> ${list.length===0?`<divclass="empty-state"><i class="fasfa-heart"></i><p>Wishlist is empty.</p><buttonclass="btn-enroll" onclick="showPage('courses')">BrowseCourses</button></div>`: `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:12px">${list.map(c=>`<divclass="cc"><div class="cc-thumb"style="background:linear-gradient(135deg,${c.bg}22,${c.bg}44);height:90px">${c.emoji}</div><divclass="cc-body"><divclass="cc-title">${c.title}</div><divclass="cc-footer"><div class="cc-price">₹${c.price.toLocaleString()}</div><buttonclass="btn-enroll"onclick="enrollCourse(${c.id})">Enroll</button></div></div></div>`).join('')}</div>`}`;} function renderGameplay(){ const u=S.user; document.getElementById('dashMain').innerHTML=`<div class="dash-hdr"><div><h2>Badges &XP</h2><p>Your achievements</p></div></div><div class="dash-geq"> <div class="dash-card"style="text-align:center"><divstyle="font-size:2.2rem;font-weight:800;color:var(--gold);font-family:'SpaceGrotesk',sans-serif">${u.xp||0}</div><divstyle="font-size:12px;color:var(--text2);margin-top:3px">TotalXP</div><div class="prog-bar" style="margin:11px 03px"><div class="prog-fill"style="width:${Math.min((u.xp||0)/50,100)}%"></div></div><divstyle="font-size:11px;color:var(--text2)">Earn by completingcourses & quizzes</div></div> <divclass="streak-card"><div style="font-size:10px;color:var(--text2);margin-bottom:2px"> STREAK</div><divclass="streak-num">${u.streak||1}</div><divstyle="font-size:11px;color:var(--text2)">days in arow</div><divclass="week-dots">${['M','T','W','T','F','S','S'].map((d,i)=>`<divclass="wd${i<5?'wd-done':i===5?'wd-today':'wd-future'}">${d}</div>`).join('')}</div></div></div> <div class="dash-card"> <divclass="dc-title">Badges</div> <divclass="badge-grid">${[{e:' ',n:'FirstLaunch',earned:S.enrolledCourses.length>0},{e:' ',n:'HotStreak',earned:false},{e:' ',n:'CodeNinja',earned:false},{e:' ',n:'QuizMaster',earned:false},{e:' ',n:'SpeedLearn',earned:false},{e:' ',n:'Graduate',earned:false},{e:' ',n:'TopRanker',earned:false},{e:' ',n:'Diamond',earned:false}].map(b=>`<divclass="badge-item ${b.earned?'earned':'locked'}"><divclass="badge-emoji">${b.e}</div><divclass="badge-name">${b.n}</div>${b.earned?'':'<div style="font-size:9px;color:var(--text2);margin-top:3px"><iclass="fasfa-lock"></i></div>'}</div>`).join('')}</div></div>`; } function renderLB(){ const u=S.user;constnm=getDisplayName(u); const users=[{name:'Karthik V.',pts:8920,badge:' ',av:'KV',color:'#7c4dff'},{name:'PriyaM.',pts:7340,badge:' ',av:'PM',color:'#0891b2'},{name:'ArjunV.',pts:6180,badge:' ',av:'AV',color:'#059669'},{name:`${nm}(You)`,pts:u.xp||0,badge:' ',av:getInit(u),color:'#00e5ff',you:true},{name:'DeepaK.',pts:2640,badge:'',av:'DK',color:'#dc2626'},{name:'MohanR.',pts:1980,badge:'',av:'MR',color:'#2563eb'}].sort((a,b)=>b.pts-a.pts);document.getElementById('dashMain').innerHTML=` <div class="dash-hdr"><div><h2>Leaderboard</h2><p>Toplearners · June 2026</p></div></div> <divclass="dash-card"style="max-width:500px">${users.map((u,i)=>`<divclass="lb-item"style="${u.you?'background:rgba(0,229,255,.05);border-radius:8px;padding:2px6px;':''}"><div class="lb-rank${i===0?'r-gold':i===1?'r-silver':i===2?'r-bronze':'r-other'}">${i<3?[' ',' ',' '][i]:`#${i+1}`}</div><divclass="lb-av"style="background:${u.color}22;color:${u.color}">${u.av}</div><divclass="lb-name">${u.name}${u.you?'<strongstyle="color:var(--accent)"> ← You</strong>':''}</div><divclass="lb-pts">${u.pts.toLocaleString()} XP</div><spanstyle="font-size:14px">${u.badge}</span></div>`).join('')}</div>`;} function renderSchedule(){ const events=[{day:'Today',time:'3:00PM',title:'CAN FD AdvancedSession',type:'live',color:'#00e5ff'},{day:'Today',time:'11:59PM',title:'Python DS Quizdeadline',type:'quiz',color:'#7c4dff'},{day:'Tomorrow',time:'10:00AM',title:'Automotive Embedded Module6',type:'class',color:'#0891b2'},{day:'Thu Jun 13',time:'11:00 AM',title:'RTOSDeep Dive: Tasks',type:'live',color:'#00e5ff'},{day:'Fri Jun 14',time:'11:59PM',title:'CAN Bus Assignment due',type:'assignment',color:'#ffd600'}];document.getElementById('dashMain').innerHTML=`<divclass="dash-hdr"><div><h2>Schedule</h2><p>Upcomingclasses, quizzes and deadlines</p></div></div> <divclass="dash-card">${events.map(e=>`<divstyle="display:flex;align-items:center;gap:11px;padding:10px0;border-bottom:1px solid var(--border)"><divstyle="width:6px;height:6px;border-radius:50%;background:${e.color};flex-shrink:0"></div><divstyle="min-width:80px;font-size:11px;color:var(--text2)">${e.day}</div><divstyle="min-width:60px;font-size:11px;font-weight:600">${e.time}</div><divstyle="flex:1;font-size:12px;font-weight:600">${e.title}</div><spanstyle="background:${e.color}22;color:${e.color};padding:2px7px;border-radius:4px;font-size:9px;font-weight:700">${e.type.toUpperCase()}</span></div>`).join('')}</div>`;} function renderPayments(){document.getElementById('dashMain').innerHTML=`<divclass="dash-hdr"><div><h2>Payments</h2><p>Alltransactions</p></div></div> <divclass="dash-card" style="overflow-x:auto"> <tableclass="admin-table"><thead><tr><th>Course</th><th>Amount</th><th>Method</th><th>Date</th><th>Status</th><th>Invoice</th></tr></thead><tbody>${S.enrolledCourses.map(id=>{constc=COURSES.find(x=>x.id===id);if(!c)return'';return`<tr><tdstyle="font-weight:600">${c.title}</td><tdstyle="font-weight:700;color:var(--accent)">₹${c.price.toLocaleString()}</td><td>UPI</td><td>Jun2026</td><td><span class="s-pillsp-active">PAID</span></td><td><buttonclass="abt ab-v"onclick="showToast('Downloading…','success')"><iclass="fas fa-download"></i></button></td></tr>`;}).join('')||'<tr><tdcolspan="6"style="text-align:center;color:var(--text2);padding:16px">Notransactions. Enroll to seepayments.</td></tr>'}</tbody></table> </div>`; }function renderSettings(){ const u=S.user||{};document.getElementById('dashMain').innerHTML=`<divclass="dash-hdr"><div><h2>Settings</h2><p>Accountpreferences</p></div></div> <divstyle="max-width:520px"> <div class="dash-card"style="margin-bottom:12px"> <divclass="dc-title">Profile Info</div> <divclass="form-group"><label class="form-label">FirstName</label><input class="form-input" id="sFname"value="${u.firstName||''}"></div> <divclass="form-group"><label class="form-label">LastName</label><input class="form-input" id="sLname"value="${u.lastName||''}"></div> <divclass="form-group"><labelclass="form-label">Email</label><input class="form-input"id="sEmail" value="${u.email||''}"></div> <divclass="form-group"><labelclass="form-label">Phone</label><inputclass="form-input" id="sPhone" value="${u.phone||''}"></div><div class="form-group"><labelclass="form-label">City</label><inputclass="form-input" id="sCity"value="${u.city||''}"></div> <buttonclass="btn-enroll" onclick="saveSettings()">SaveChanges</button> </div> <div class="dash-card"style="margin-bottom:12px"> <divclass="dc-title">Notifications</div> ${[['Emailnotifications',true],['Push notifications',true],['Assignmentreminders',false],['Community replies',true]].map(n=>`<divstyle="display:flex;justify-content:space-between;align-items:center;padding:8px0;border-bottom:1px solid var(--border)"><spanstyle="font-size:12px">${n[0]}</span><inputtype="checkbox" ${n[1]?'checked':''}onchange="showToast('Saved','success')"style="width:14px;height:14px;accent-color:var(--accent)"></div>`).join('')}</div> <div class="dash-card"> <divclass="dc-title">Appearance</div> <divstyle="display:flex;align-items:center;justify-content:space-between;padding:8px0"><spanstyle="font-size:12px">Theme</span><buttonclass="btn-enroll"onclick="toggleTheme()">Toggle</button></div> <divclass="form-group" style="margin-top:8px"><labelclass="form-label">Language</label><selectclass="form-input" onchange="showToast('Language saved','success')"><option>English</option><option>Tamil</option><option>Hindi</option><option>Telugu</option></select></div><div style="margin-top:11px;padding-top:11px;border-top:1px solid var(--border)"><buttonstyle="padding:7px14px;background:rgba(255,61,113,.1);color:var(--accentr);border:1px solidrgba(255,61,113,.25);border-radius:7px;font-size:11px;font-weight:600;cursor:pointer"onclick="doLogout()"><i class="fasfa-sign-out-alt"></i> Logout</button></div></div> </div>`; } function saveSettings(){if(!S.user)return;S.user.firstName=document.getElementById('sFname').value.trim();S.user.lastName=document.getElementById('sLname').value.trim();S.user.email=document.getElementById('sEmail').value.trim();S.user.phone=document.getElementById('sPhone').value.trim();S.user.city=document.getElementById('sCity').value.trim();localStorage.setItem('ts_user',JSON.stringify(S.user));afterLogin();showToast('Profilesaved!','success');} /* PROFILE */ function renderProfilePage(){ constu=S.user;if(!u)return; const init=getInit(u);const nm=getDisplayName(u);document.getElementById('profAv').textContent=init;document.getElementById('profName').textContent=nm;document.getElementById('profTagline').textContent=[u.role,u.city].filter(Boolean).join('· ')||'TS Tech Park Learner';document.getElementById('profEmail').innerHTML=`<i class="fasfa-envelope"></i> ${u.email||'—'}`;document.getElementById('profPhone').innerHTML=`<i class="fasfa-phone"></i> ${u.phone||'—'}`; document.getElementById('profJoined').innerHTML=`<iclass="fas fa-calendar"></i> Joined ${u.joinedDate||'—'}`;document.getElementById('profStats').innerHTML=[{label:'Enrolled',val:S.enrolledCourses.length},{label:'Hours',val:(u.hoursLearned||0)+'h'},{label:'Certificates',val:u.certificates||0},{label:'XP',val:`<spanstyle="color:var(--gold);font-weight:800">${u.xp||0}</span>`},{label:'Streak ',val:u.streak||1}].map(s=>`<divclass="psl-item"><spanclass="psl-label">${s.label}</span><spanclass="psl-val">${s.val}</span></div>`).join('');document.getElementById('profCerts').innerHTML=[{name:'Python for DataScience',date:'Mar 2025',c:'#2563eb'},{name:'Embedded SystemsFundamentals',date:'May 2025',c:'#0891b2'}].map(cert=>`<divstyle="display:flex;align-items:center;gap:9px;padding:9px0;border-bottom:1px solid var(--border)"><divstyle="width:30px;height:30px;border-radius:7px;background:${cert.c}22;color:${cert.c};display:flex;align-items:center;justify-content:center;font-size:14px"><iclass="fasfa-certificate"></i></div><div><divstyle="font-weight:700;font-size:12px">${cert.name}</div><divstyle="font-size:10px;color:var(--text2)">${cert.date}</div></div><buttonclass="abt ab-v" style="margin-left:auto"onclick="showToast('Opening…','info')">View</button></div>`).join('');document.getElementById('profSkills').innerHTML=[{s:'EmbeddedC',p:90},{s:'CAN/LIN Protocol',p:85},{s:'Python',p:78},{s:'RTOS',p:70},{s:'ML',p:60},{s:'Cloud',p:45}].map(sk=>`<divstyle="margin-bottom:9px"><divstyle="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px"><span>${sk.s}</span><strong>${sk.p}%</strong></div><divclass="prog-bar"><div class="prog-fill"style="width:${sk.p}%"></div></div></div>`).join('');const cells=Array.from({length:84},()=>{const r=Math.random();returnr<.3?0:r<.55?1:r<.75?2:r<.9?3:4;});document.getElementById('profHeatmap').innerHTML=`<divstyle="font-size:10px;color:var(--text2);margin-bottom:6px">Last84 days</div><divclass="heatmap-grid">${cells.map(c=>`<divclass="heat-cell h${c}"></div>`).join('')}</div>`; }function openEditProfile(){ const u=S.user;if(!u){openAuth('login');return;}document.getElementById('editProfileBody').innerHTML=`<divclass="form-row"><div class="form-group"><labelclass="form-label">First Name</label><inputclass="form-input" id="epFn"value="${u.firstName||''}"></div><divclass="form-group"><label class="form-label">LastName</label><input class="form-input" id="epLn"value="${u.lastName||''}"></div></div><divclass="form-group"><labelclass="form-label">Email</label><inputclass="form-input" id="epEm"value="${u.email||''}"></div><divclass="form-group"><labelclass="form-label">Phone</label><inputclass="form-input" id="epPh" value="${u.phone||''}"></div><divclass="form-group"><labelclass="form-label">City</label><inputclass="form-input" id="epCi"value="${u.city||''}"></div><button class="btn-fullbtn-accent" onclick="saveEP()">Save Profile</button>`;document.getElementById('editProfileModal').classList.add('active'); } functionsaveEP(){constu=S.user;u.firstName=document.getElementById('epFn').value.trim();u.lastName=document.getElementById('epLn').value.trim();u.email=document.getElementById('epEm').value.trim();u.phone=document.getElementById('epPh').value.trim();u.city=document.getElementById('epCi').value.trim();localStorage.setItem('ts_user',JSON.stringify(u));closeModal('editProfileModal');afterLogin();renderProfilePage();showToast('Updated!','success');}/* FORUM */ function renderForum(filter='',tab='all'){ constc=document.getElementById('forumPosts');if(!c)return; let posts=S.forumPosts;if(filter)posts=posts.filter(p=>p.title.toLowerCase().includes(filter.toLowerCase())||p.text.toLowerCase().includes(filter.toLowerCase())||p.tags.some(t=>t.toLowerCase().includes(filter.toLowerCase())));if(tab!=='all')posts=posts.filter(p=>p.type===tab);c.innerHTML=posts.length===0?`<div class="empty-state"><i class="fasfa-comments"></i><p>No posts yet. Be thefirst!</p></div>`: posts.map(p=>`<divclass="fp"><div class="fp-hdr"><divclass="fp-av"style="background:${p.color}22;color:${p.color}">${p.av}</div><divclass="fp-meta"><divclass="fp-name">${p.user}</div><divclass="fp-time">${p.time}</div></div><spanclass="fp-cat"style="background:${p.catColor}22;color:${p.catColor}">${p.cat}</span></div><divclass="fp-title">${p.title}</div><divclass="fp-text">${p.text}</div><divclass="fp-tags">${p.tags.map(t=>`<spanclass="tag-pill">#${t}</span>`).join('')}</div><divclass="fp-foot"><button class="fp-act"onclick="likePost(this)"><i class="fasfa-heart"></i>${p.likes}</button><buttonclass="fp-act" onclick="showToast('Openingreplies…','info')"><i class="fasfa-comment"></i>${p.replies} replies</button><buttonclass="fp-act"onclick="showToast('Saved!','success')"><i class="fas fa-bookmark"></i></button><buttonclass="fp-act" style="margin-left:auto"onclick="showToast('Link copied!','info')"><i class="fasfa-share"></i></button></div></div>`).join('');} function filterForum(val){renderForum(val||'',S.forumTab);} functionsetForumTab(btn,tab){document.querySelectorAll('.ftab').forEach(b=>b.classList.remove('active'));btn.classList.add('active');S.forumTab=tab;renderForum('',tab);}function likePost(btn){const i=btn.querySelector('i');constliked=i.style.color==='var(--accentr)';i.style.color=liked?'':'var(--accentr)';constn=parseInt(btn.textContent.match(/\d+/)[0]);btn.innerHTML=`<iclass="fas fa-heart" style="color:${liked?'':'var(--accentr)'}"></i>${liked?n-1:n+1}`;}functionopenNewPost(){if(!S.loggedIn){openAuth('login');return;}document.getElementById('postModal').classList.add('active');}function submitPost(){ consttitle=document.getElementById('postTitle').value.trim(); const content=document.getElementById('postContent').value.trim();const cat=document.getElementById('postCat').value; consttags=document.getElementById('postTags').value.split(',').map(t=>t.trim()).filter(Boolean);if(!title||!content){showToast('Fill title and content','error');return;} constu=S.user;S.forumPosts.unshift({id:Date.now(),user:getDisplayName(u),av:getInit(u),color:'#00e5ff',time:'Justnow',cat,catColor:'#0891b2',title,text:content,likes:0,replies:0,tags:tags.length?tags:[cat],type:'questions'});closeModal('postModal');renderForum();document.getElementById('postTitle').value='';document.getElementById('postContent').value='';document.getElementById('postTags').value='';showToast('Published! ','success'); } /* LIVE*/ function renderLive(tab){ constc=document.getElementById('liveContent');if(!c)return; constlist=LIVE_DATA[tab]||[]; if(!list.length){c.innerHTML=`<divclass="empty-state"><i class="fas fa-video"></i><p>Nosessions right now.</p></div>`;return;}c.innerHTML=list.map(lc=>`<div class="lcc"><divclass="lc-ico"style="background:${tab==='live'?'rgba(255,61,113,.1)':'rgba(0,229,255,.1)'}">${lc.emoji}</div><divstyle="flex:1">${tab==='live'?'<divclass="lc-live"><div class="ldot"></div>LIVENOW</div>':''}<divstyle="font-weight:700;font-size:13px">${lc.title}</div><divstyle="font-size:11px;color:var(--text2);margin-top:2px"><iclass="fas fa-user-tie" style="margin-right:3px"></i>${lc.instructor}<iclass="fas fa-clock" style="margin:0 3px 08px"></i>${lc.time}${lc.attendees?`<i class="fasfa-users" style="margin:0 3px 0 8px"></i>${lc.attendees}`:''}${lc.duration?`<i class="fas fa-film" style="margin:0 3px 08px"></i>${lc.duration}`:''}</div></div><buttonclass="btn-enroll" onclick="showToast('${tab==='live'?'Joining…':tab==='recordings'?'Loading…':'Reminderset! '}','${tab==='live'?'success':'info'}')">${tab==='live'?'<i class="fas fa-video"></i>Join':tab==='recordings'?'<i class="fas fa-play"></i>Watch':'<i class="fas fa-bell"></i> Remind'}</button></div>`).join('');} functionsetLiveTab(btn,tab){document.querySelectorAll('.ltab').forEach(b=>b.classList.remove('active'));btn.classList.add('active');renderLive(tab);}/* ADMIN */ function getAdminUsers(){const accounts=JSON.parse(localStorage.getItem('ts_accounts')||'[]');constextra=accounts.map(a=>({name:[a.firstName,a.lastName].filter(Boolean).join('')||a.email,email:a.email,role:a.role||'Student',enrolled:0,status:'active',joined:a.joinedDate||'Recently'}));return[...ADMIN_USERS,...extra];}function renderAdminTable(){ const tb=document.getElementById('adminTableBody');if(!tb)return;let users=getAdminUsers();if(S.adminFilter)users=users.filter(u=>u.name.toLowerCase().includes(S.adminFilter.toLowerCase())||u.email.toLowerCase().includes(S.adminFilter.toLowerCase()));if(S.adminRole)users=users.filter(u=>u.role===S.adminRole); constpp=6,total=Math.ceil(users.length/pp),page=Math.min(S.adminPage,total); constpaged=users.slice((page-1)*pp,page*pp); tb.innerHTML=paged.map(u=>{constav=(u.name||'?').split(' ').map(n=>n[0]).join('').substring(0,2).toUpperCase();return`<tr><tdstyle="display:flex;align-items:center;gap:7px"><divstyle="width:28px;height:28px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;color:#000;font-size:9px;font-weight:800;flex-shrink:0">${av}</div><strongstyle="font-size:12px">${u.name}</strong></td><tdstyle="color:var(--text2);font-size:11px">${u.email}</td><td><spanstyle="padding:2px 7px;border-radius:4px;font-size:9px;font-weight:700;background:${u.role==='Instructor'?'rgba(124,77,255,.12)':'rgba(0,229,255,.12)'};color:${u.role==='Instructor'?'#7c4dff':'var(--accent)'}">${u.role}</span></td><td>${u.enrolled}</td><td><spanclass="s-pillsp-${u.status}">${u.status.toUpperCase()}</span></td><tdstyle="font-size:11px">${u.joined}</td><td><divclass="act-btns"><button class="abt ab-v"onclick="showToast('Opening…','info')">View</button><buttonclass="abt ab-e"onclick="showToast('Editing…','info')">Edit</button><buttonclass="abt ab-d"onclick="showToast('Suspended','error')">Suspend</button></div></td></tr>`;}).join('');const pag=document.getElementById('tablePag');if(pag)pag.innerHTML=Array.from({length:total},(_,i)=>`<buttonclass="pg-btn ${i+1===page?'active':''}"onclick="S.adminPage=${i+1};renderAdminTable()">${i+1}</button>`).join('');} function filterAdminUsers(val){if(val!==undefined)S.adminFilter=val;constr=document.getElementById('adminRoleFilter');if(r)S.adminRole=r.value;S.adminPage=1;renderAdminTable();}function renderAdminChart(){const c=document.getElementById('revChart');if(!c)return;constvals=[45,72,58,91,63,88,76];constmax=Math.max(...vals);c.innerHTML=vals.map(v=>`<divclass="rev-bar" style="height:${Math.round(v/max*100)}%"title="₹${v*1000}"></div>`).join('');} function renderAdminTop(){constc=document.getElementById('adminTopCourses');if(!c)return;c.innerHTML=[['AutomotiveEmbedded','₹1.8L',32],['Edge AI','₹1.2L',18],['PythonDS','₹0.9L',24],['RTOS','₹0.7L',15]].map(([n,r,s])=>`<divstyle="padding:8px 0;border-bottom:1px solid var(--border)"><divstyle="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px"><spanstyle="font-weight:600">${n}</span><spanstyle="font-weight:700;color:var(--green)">${r}</span></div><divclass="prog-bar"><div class="prog-fill"style="width:${s*3}%"></div></div><span style="font-size:9px;color:var(--text2)">${s}enrollments</span></div>`).join('');} functionrenderAdminLog(){constc=document.getElementById('adminActivityLog');if(!c)return;[{icon:'fa-user-plus',cls:'ad-g',msg:'Newsignup: Deepa K.',time:'5 min ago'},{icon:'fa-book',cls:'ad-b',msg:'Courseenrolled: Edge AI',time:'12 minago'},{icon:'fa-rupee-sign',cls:'ad-y',msg:'Payment: ₹60,000 received',time:'1hr ago'},{icon:'fa-certificate',cls:'ad-p',msg:'Certificate issued: ArjunV.',time:'2 hr ago'},{icon:'fa-flag',cls:'ad-r',msg:'Report flagged: Forum post#8',time:'3 hr ago'}].forEach(l=>{c.innerHTML+=`<divclass="act-item"><div class="act-dot${l.cls}"><i class="fas ${l.icon}"style="font-size:10px"></i></div><div><divclass="act-title"style="font-size:12px">${l.msg}</div><divclass="act-time">${l.time}</div></div></div>`;});}/* CHATBOT */ function setChatLang(lang){S.chatLang=lang;document.getElementById('chatMsgs').innerHTML='';S.chatWarnings=0;chatWelcome();}function chatWelcome(){const lang=FAQ[S.chatLang]||FAQ.en;addBotMsg(lang.welcome||FAQ.en.welcome);}functiontoggleChat(){S.chatOpen=!S.chatOpen;document.getElementById('chatPanel').classList.toggle('open',S.chatOpen);document.getElementById('chatIcon').className=S.chatOpen?'fasfa-times':'fas fa-robot';if(S.chatOpen){document.getElementById('chatUnread').style.display='none';document.getElementById('chatInput').focus();}}functionclearChat(){document.getElementById('chatMsgs').innerHTML='';S.chatWarnings=0;chatWelcome();showToast('Chatcleared','info');} function sendChat(){ constinput=document.getElementById('chatInput'); constmsg=input.value.trim();if(!msg)return; input.value='';input.style.height='';document.getElementById('chatSugg').style.display='none'; constlower=msg.toLowerCase(); const isBad=BAD.some(w=>lower.includes(w));if(isBad){ S.chatWarnings++;addUserMsg(msg); constlang=FAQ[S.chatLang]||FAQ.en; constwm=S.chatWarnings===1?lang.warn1:S.chatWarnings===2?lang.warn2:lang.warn3;setTimeout(()=>addBotMsg(`<div class="warn-msg"><iclass="fas fa-exclamation-triangle"></i>${wm}</div>`),500);return; } addUserMsg(msg); const td='ty_'+Date.now();constmsgs=document.getElementById('chatMsgs'); consttd2=document.createElement('div');td2.id=td;td2.className='cmr'; td2.innerHTML=`<divclass="msg-av-sm bot-av-sm"><i class="fas fa-robot"style="font-size:8px"></i></div><divclass="msg-bubble bot-bub"><divclass="typing-indicator"><div class="typing-dot"></div><divclass="typing-dot"></div><divclass="typing-dot"></div></div></div>`;msgs.appendChild(td2);scrollChat();setTimeout(()=>{td2.remove();addBotMsg(getBotReply(msg));},700+Math.random()*400);} functionsendSugg(text){document.getElementById('chatInput').value=text;sendChat();}function getBotReply(msg){ const lang=FAQ[S.chatLang]||FAQ.en; constm=msg.toLowerCase(); const faq=lang.faq||{}; const efaq=FAQ.en.faq;for(const[k,v]of Object.entries(faq)){if(m.includes(k))return v;}for(const[k,v]of Object.entries(efaq)){if(m.includes(k))return v;}if(m.includes('price')||m.includes('cost')||m.includes('fee')||m.includes('கட்டணம்')||m.includes('फीस'))return efaq['fee'];if(m.includes('batch')||m.includes('start')||m.includes('when'))returnefaq['batch'];if(m.includes('placement')||m.includes('job')||m.includes('salary'))returnefaq['placement']; if(m.includes('cert'))return efaq['certificate']; if(m.includes('contact')||m.includes('address'))returnefaq['contact']; if(m.includes('recommend')||m.includes('best course'))returnefaq['recommend']; return lang.fallback||FAQ.en.fallback; } functionaddBotMsg(html){const msgs=document.getElementById('chatMsgs');constd=document.createElement('div');d.className='cmr';d.innerHTML=`<divclass="msg-av-sm bot-av-sm"><i class="fas fa-robot"style="font-size:8px"></i></div><divclass="msg-bubble bot-bub">${html}</div>`;msgs.appendChild(d);scrollChat();}function addUserMsg(text){const msgs=document.getElementById('chatMsgs');constd=document.createElement('div');d.className='cmr user';d.innerHTML=`<divclass="msg-bubble user-bub">${escHtml(text)}</div><divclass="msg-av-sm user-av-sm">U</div>`;msgs.appendChild(d);scrollChat();}function scrollChat(){constm=document.getElementById('chatMsgs');m.scrollTop=m.scrollHeight;} functionautoResizeChat(el){el.style.height='';el.style.height=Math.min(el.scrollHeight,80)+'px';}function escHtml(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}/* TOASTS */ constTI={success:'fa-check-circle',error:'fa-exclamation-circle',info:'fa-info-circle',warning:'fa-exclamation-triangle'};function showToast(msg,type='info'){const c=document.getElementById('toastContainer');constt=document.createElement('div');t.className=`toast ${type}`;t.innerHTML=`<iclass="fas${TI[type]}"></i>${msg}`;c.appendChild(t);requestAnimationFrame(()=>t.classList.add('show'));setTimeout(()=>{t.classList.remove('show');setTimeout(()=>t.remove(),280);},3400);}</script> </body> </html>
